1	//! The `build` subcommand: build the workspace's release, or with
2	//! `--dev` its dev build, each by its configured command list. The
3	//! dev build was `build-dev`, a command of its own, until every
4	//! variant became a flag, and `build-dev` is kept hidden to be
5	//! refused naming `build --dev`. Neither build touches the PATH: that
6	//! is `vc-x1 install`'s, which copies them there.
7	//!
8	//! - `vc-x1 build` runs `[build] release`, here
9	//!   `cargo build --release --locked`, and checks it left its binary
10	//!   at `[build] release-bin`. The lists leave the binaries in
11	//!   `target/`, off the PATH, so nothing there is replaced: the
12	//!   release build is run by `vc-x1 run` and copied by
13	//!   `vc-x1 install`, which runs this same build first, through
14	//!   [`build_params`] and [`build`].
15	//! - `vc-x1 build --dev` runs `[build] dev`, the dev build, which
16	//!   `vc-x1 install --dev` runs first and copies.
17	//! - Where a build leaves its binary is the config's to say,
18	//!   `release-bin` and `dev-bin`: vc-x1 never works it out from cargo
19	//!   or the package's name.
20	//! - Both run their commands with the build's [`Provenance`] in the
21	//!   environment, `VC_X1_BUILD_COMMIT` and `VC_X1_BUILD_STATE`, as
22	//!   `validate` does, so every build of a run sees the same values
23	//!   and none recompiles for another. An artifact that compiles them
24	//!   in can say what it was built from wherever it is copied. vc-x1
25	//!   does, as semver build metadata in its banner,
26	//!   `0.85.7+d70cf9ecdfd9`, `.dirty` for a build with edits.
27	//! - Neither checks the repo's state: a release may be built from a
28	//!   cycle's bookmark, to try the release profile mid-cycle.
29	//! - Neither tracks whether its binary is out of date: cargo does,
30	//!   rebuilding only what changed, so vc-x1 runs the list every time.
31	//! - The lists are run by [`crate::command_list`], as `validate`'s
32	//!   are.
33	//! - `--dry-run` prints the list and runs nothing, as `run` prints
34	//!   the build it would run first.
35	
36	use std::path::{Path, PathBuf};
37	
38	use clap::Args;
39	use log::{debug, info, warn};
40	
41	use crate::context::Context;
42	use crate::options_flags::dry_run::DryRunFlag;
43	use crate::subcommand::SubcommandRunner;
44	use crate::version::SourceState;
45	
46	/// The variable carrying the build's commit to its commands.
47	pub const BUILD_COMMIT_VAR: &str = "VC_X1_BUILD_COMMIT";
48	
49	/// The variable carrying `state`, the state of the source code being
50	/// compiled, `clean` or `dirty`.
51	pub const BUILD_STATE_VAR: &str = "VC_X1_BUILD_STATE";
52	
53	/// Build the release, or with `--dev` the dev build.
54	#[derive(Args, Debug)]
55	pub struct BuildArgs {
56	    /// Build the dev build, `[build] dev`, instead of the release
57	    #[arg(short = 'd', long)]
58	    pub dev: bool,
59	
60	    #[command(flatten)]
61	    pub dry_run: DryRunFlag,
62	
63	    /// Workspace to build from [default: the workspace containing
64	    /// the current directory]
65	    #[arg(short = 'R', long, value_name = "DIR")]
66	    pub repo: Option<PathBuf>,
67	}
68	
69	/// Retired: `build-dev`, now `build --dev`, refused naming it. Its
70	/// flags are kept so an old invocation parses and is told the fix.
71	#[derive(Args, Debug)]
72	pub struct BuildDevArgs {
73	    #[command(flatten)]
74	    pub dry_run: DryRunFlag,
75	
76	    /// Workspace to build from [default: the workspace containing
77	    /// the current directory]
78	    #[arg(short = 'R', long, value_name = "DIR")]
79	    pub repo: Option<PathBuf>,
80	}
81	
82	/// What a build is made from: the work repo's `@-` and the state of
83	/// its source, read before the build runs.
84	#[derive(Debug, Clone, PartialEq, Eq)]
85	pub struct Provenance {
86	    /// The full commit id of the work repo's `@-`.
87	    pub commit: String,
88	    /// The state of the source code being compiled: clean when the
89	    /// work repo's `@` was empty, so the compiled code is exactly
90	    /// `commit`'s tree, else dirty. Never unknown, since it is read
91	    /// through jj.
92	    pub state: SourceState,
93	}
94	
95	impl Provenance {
96	    /// Read the provenance of the work repo at `root`, `label`
97	    /// prefixing an error.
98	    pub fn read(root: &Path, label: &str) -> Result<Self, String> {
99	        let commit = crate::jj::cid_of(root, "@-")
100	            .map_err(|e| format!("{label}: the commit `@-` in '{}': {e}", root.display()))?;
101	        let empty = crate::jj::is_empty(root, "@")
102	            .map_err(|e| format!("{label}: whether `@` is empty in '{}': {e}", root.display()))?;
103	        let state = if empty {
104	            SourceState::Clean
105	        } else {
106	            SourceState::Dirty
107	        };
108	        Ok(Provenance { commit, state })
109	    }
110	
111	    /// Read it, or warn and carry none, for a build that runs
112	    /// without it: the dev build and `validate`'s.
113	    pub fn read_or_warn(root: &Path, label: &str) -> Option<Self> {
114	        match Self::read(root, label) {
115	            Ok(p) => Some(p),
116	            Err(e) => {
117	                warn!("{e}, so the build carries no commit");
118	                None
119	            }
120	        }
121	    }
122	
123	    /// The two variables the build's commands get.
124	    pub fn env(&self) -> [(&'static str, &str); 2] {
125	        [
126	            (BUILD_COMMIT_VAR, self.commit.as_str()),
127	            (BUILD_STATE_VAR, self.state.as_str()),
128	        ]
129	    }
130	}
131	
132	/// The variables for `provenance`, none when it is absent.
133	pub fn build_env(provenance: Option<&Provenance>) -> Vec<(&'static str, &str)> {
134	    // OK: no provenance is no variables, the build carrying no commit
135	    provenance.map(|p| p.env().to_vec()).unwrap_or_default()
136	}
137	
138	/// Per-invocation build inputs: the command's label, the list's key,
139	/// its commands, the directory to run them from, the build's
140	/// provenance, and the binary a release leaves.
141	#[derive(Debug)]
142	pub struct BuildParams {
143	    /// `build` or `build --dev`, prefixing the run's messages.
144	    pub label: &'static str,
145	    /// `build.release` or `build.dev`.
146	    pub key: &'static str,
147	    /// The commands, one element per invocation.
148	    pub commands: Vec<String>,
149	    /// The work repo root the commands run from.
150	    pub root: PathBuf,
151	    /// The build's provenance, required for a release, best effort
152	    /// for the dev build.
153	    pub provenance: Option<Provenance>,
154	    /// The binary a release leaves, `[build] release-bin`, `None` for
155	    /// the dev build.
156	    pub bin: Option<PathBuf>,
157	    /// Print the list and run nothing.
158	    pub dry_run: bool,
159	}
160	
161	impl TryFrom<&BuildArgs> for BuildParams {
162	    type Error = String;
163	
164	    /// The release, or the dev build with `--dev`: see [`build_params`].
165	    fn try_from(a: &BuildArgs) -> Result<Self, String> {
166	        let mut params = build_params(a.dev, a.repo.as_deref())?;
167	        params.dry_run = a.dry_run.value;
168	        Ok(params)
169	    }
170	}
171	
172	impl TryFrom<&BuildDevArgs> for BuildParams {
173	    type Error = String;
174	
175	    /// Refused: `build-dev` is `build --dev`.
176	    fn try_from(_: &BuildDevArgs) -> Result<Self, String> {
177	        Err(retired_dev("build"))
178	    }
179	}
180	
181	/// The refusal for a retired `<command>-dev`, naming `<command> --dev`.
182	pub fn retired_dev(command: &str) -> String {
183	    format!(
184	        "{command}-dev: the -dev commands are retired, the dev build is a flag: \
185	         `{command} --dev`"
186	    )
187	}
188	
189	/// Resolve the workspace root (from `-R` or the cwd), take the chosen
190	/// list, read the provenance, and for a release resolve `release-bin`.
191	/// A release's every miss is an error here, before anything runs, and
192	/// the dev build's provenance is best effort.
193	pub fn build_params(dev: bool, repo: Option<&Path>) -> Result<BuildParams, String> {
194	    let (label, key) = if dev {
195	        ("build --dev", "build.dev")
196	    } else {
197	        ("build", "build.release")
198	    };
199	    let root = match repo {
200	        Some(p) => crate::common::find_workspace_root_from(p)
201	            .ok_or_else(|| format!("{label}: '{}' is not in a vc-x1 workspace", p.display()))?,
202	        None => crate::common::find_workspace_root()
203	            .ok_or_else(|| format!("{label}: not in a vc-x1 workspace (no config found)"))?,
204	    };
205	    let commands = crate::command_list::load(&root, key, label)?;
206	    let (provenance, bin) = if dev {
207	        (Provenance::read_or_warn(&root, label), None)
208	    } else {
209	        let bin = release_bin(&root)?;
210	        (Some(Provenance::read(&root, label)?), Some(bin))
211	    };
212	    Ok(BuildParams {
213	        label,
214	        key,
215	        commands,
216	        root,
217	        provenance,
218	        bin,
219	        dry_run: false,
220	    })
221	}
222	
223	/// `[build] release-bin` at `root`: see [`bin_at`]. Required for a
224	/// release, whose build is checked for it and which `install` copies.
225	pub fn release_bin(root: &Path) -> Result<PathBuf, String> {
226	    bin_at(
227	        root,
228	        "build.release-bin",
229	        "the binary `build.release` leaves, which `install` copies",
230	    )
231	}
232	
233	/// `[build] dev-bin` at `root`: see [`bin_at`]. Required by
234	/// `install-dev`, which copies it.
235	pub fn dev_bin(root: &Path) -> Result<PathBuf, String> {
236	    bin_at(
237	        root,
238	        "build.dev-bin",
239	        "the binary `build.dev` leaves, which `install-dev` copies",
240	    )
241	}
242	
243	/// The binary `key` names at `root`, resolved against the config
244	/// file's directory, or as is when absolute, `what` saying in its
245	/// absence what the key is for.
246	fn bin_at(root: &Path, key: &str, what: &str) -> Result<PathBuf, String> {
247	    let cfg = crate::config_md::load(root)
248	        .map_err(|e| format!("build: {e}"))?
249	        .ok_or_else(|| format!("build: no config in '{}'", root.display()))?;
250	    let value = crate::toml_simple::toml_get(&cfg.map, key).ok_or_else(|| {
251	        format!(
252	            "build: {}: no `{key}`, {what} (see `vc-x1 config -s work`)",
253	            cfg.path.display()
254	        )
255	    })?;
256	    // OK: a loaded config's path is a file, so it has a parent
257	    let cfg_dir = cfg.path.parent().unwrap_or(root);
258	    Ok(crate::common::resolve_repo_path(cfg_dir, value))
259	}
260	
261	impl SubcommandRunner for BuildArgs {
262	    type Params = BuildParams;
263	
264	    /// Delegate to the `TryFrom<&BuildArgs>` impl above.
265	    fn to_params(&self) -> Result<Self::Params, String> {
266	        BuildParams::try_from(self)
267	    }
268	
269	    /// Run the `build` op (`ctx` unused: the op is fully
270	    /// parameterized by `Params`).
271	    fn run(_ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
272	        build(params)
273	    }
274	}
275	
276	impl SubcommandRunner for BuildDevArgs {
277	    type Params = BuildParams;
278	
279	    /// Delegate to the `TryFrom<&BuildDevArgs>` impl above.
280	    fn to_params(&self) -> Result<Self::Params, String> {
281	        BuildParams::try_from(self)
282	    }
283	
284	    /// Run the same op as `build`, its params naming the dev build.
285	    fn run(_ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
286	        build(params)
287	    }
288	}
289	
290	/// Run the list from the root with the provenance in its
291	/// environment, and for a release check it left its binary. A dry
292	/// run prints the list and runs nothing.
293	pub fn build(params: &BuildParams) -> Result<(), Box<dyn std::error::Error>> {
294	    debug!("{}: entry params={params:?}", params.label);
295	    if params.dry_run {
296	        let n = params.commands.len();
297	        for (i, command) in params.commands.iter().enumerate() {
298	            info!("{}: [dry-run] [{}/{n}] {command}", params.label, i + 1);
299	        }
300	        info!("{}: [dry-run] ran nothing ({})", params.label, params.key);
301	        return Ok(());
302	    }
303	    let env = build_env(params.provenance.as_ref());
304	    crate::command_list::run(
305	        &params.root,
306	        params.key,
307	        &params.commands,
308	        &env,
309	        &[],
310	        params.label,
311	    )?;
312	    let (Some(bin), Some(provenance)) = (&params.bin, &params.provenance) else {
313	        return Ok(());
314	    };
315	    if !bin.is_file() {
316	        return Err(format!(
317	            "build: `{}` passed but left no binary at '{}': check `build.release-bin`",
318	            params.key,
319	            bin.display()
320	        )
321	        .into());
322	    }
323	    let short = &provenance.commit[..provenance.commit.len().min(12)];
324	    let state = match provenance.state {
325	        SourceState::Clean => "state clean, `@` empty",
326	        _ => "state dirty, `@` held edits, so the build is not exactly that commit",
327	    };
328	    info!("build: {}, from {short}, {state}", bin.display());
329	    Ok(())
330	}
331	
332	#[cfg(test)]
333	mod tests {
334	    use super::*;
335	    use crate::{Cli, Commands};
336	    use clap::Parser;
337	
338	    fn parse(args: &[&str]) -> BuildArgs {
339	        let cli = Cli::try_parse_from(args).unwrap();
340	        match cli.command {
341	            Some(Commands::Build(a)) => a,
342	            _ => panic!("expected Build"),
343	        }
344	    }
345	
346	    fn parse_dev(args: &[&str]) -> BuildDevArgs {
347	        let cli = Cli::try_parse_from(args).unwrap();
348	        match cli.command {
349	            Some(Commands::BuildDev(a)) => a,
350	            _ => panic!("expected BuildDev"),
351	        }
352	    }
353	
354	    /// Unique tempdir for a one-file workspace.
355	    fn workspace(tag: &str, config: &str) -> PathBuf {
356	        let ts = std::time::SystemTime::now()
357	            .duration_since(std::time::UNIX_EPOCH)
358	            .unwrap()
359	            .as_nanos();
360	        let root = std::env::temp_dir().join(format!("vc-x1-build-{tag}-{ts}"));
361	        std::fs::create_dir_all(&root).unwrap();
362	        std::fs::write(root.join(".vc-config.md"), config).unwrap();
363	        root
364	    }
365	
366	    const COMMIT: &str = "0123456789abcdef0123456789abcdef01234567";
367	
368	    fn prov(state: SourceState) -> Provenance {
369	        Provenance {
370	            commit: COMMIT.to_string(),
371	            state,
372	        }
373	    }
374	
375	    fn release(root: &Path, commands: Vec<String>) -> BuildParams {
376	        BuildParams {
377	            label: "build",
378	            key: "build.release",
379	            commands,
380	            root: root.to_path_buf(),
381	            provenance: Some(prov(SourceState::Clean)),
382	            bin: Some(root.join("rel/bin/app")),
383	            dry_run: false,
384	        }
385	    }
386	
387	    #[test]
388	    fn flags_parse() {
389	        assert_eq!(parse(&["vc-x1", "build"]).repo, None);
390	        assert_eq!(
391	            parse(&["vc-x1", "build", "-R", "x"]).repo,
392	            Some(PathBuf::from("x"))
393	        );
394	        assert!(parse(&["vc-x1", "build", "--dev"]).dev);
395	        assert!(parse(&["vc-x1", "build", "-d"]).dev);
396	        assert!(!parse(&["vc-x1", "build"]).dev);
397	        let err =
398	            BuildParams::try_from(&parse_dev(&["vc-x1", "build-dev", "-R", "x"])).unwrap_err();
399	        assert!(err.ends_with("`build --dev`"), "{err}");
400	    }
401	
402	    /// The variables carry the commit and the state's word, and none
403	    /// without a provenance.
404	    #[test]
405	    fn build_env_forms() {
406	        assert_eq!(
407	            build_env(Some(&prov(SourceState::Clean))),
408	            vec![(BUILD_COMMIT_VAR, COMMIT), (BUILD_STATE_VAR, "clean")]
409	        );
410	        assert!(build_env(None).is_empty());
411	    }
412	
413	    /// A release without `release-bin` is refused before anything
414	    /// runs, naming the key.
415	    #[test]
416	    fn release_needs_release_bin() {
417	        let root = workspace(
418	            "nobin",
419	            "```toml\n[repos]\nwork = \".\"\n[build]\nrelease = [\"true\"]\n```\n",
420	        );
421	        let e = release_bin(&root).unwrap_err();
422	        assert!(e.contains("no `build.release-bin`"), "{e}");
423	        std::fs::remove_dir_all(&root).ok();
424	    }
425	
426	    /// `release-bin` resolves against the config file's directory,
427	    /// or as is when absolute.
428	    #[test]
429	    fn release_bin_resolves_against_the_config() {
430	        let root = workspace(
431	            "rel",
432	            "```toml\n[repos]\nwork = \".\"\n[build]\nrelease-bin = \"rel/bin/app\"\n```\n",
433	        );
434	        assert_eq!(release_bin(&root).unwrap(), root.join("rel/bin/app"));
435	        let root2 = workspace(
436	            "abs",
437	            "```toml\n[repos]\nwork = \".\"\n[build]\nrelease-bin = \"/opt/app\"\n```\n",
438	        );
439	        assert_eq!(release_bin(&root2).unwrap(), PathBuf::from("/opt/app"));
440	        std::fs::remove_dir_all(&root).ok();
441	        std::fs::remove_dir_all(&root2).ok();
442	    }
443	
444	    /// `dev-bin` resolves as `release-bin` does, and its absence names
445	    /// the key.
446	    #[test]
447	    fn dev_bin_resolves_against_the_config() {
448	        let root = workspace(
449	            "devbin",
450	            "```toml\n[repos]\nwork = \".\"\n[build]\ndev-bin = \"dbg/app\"\n```\n",
451	        );
452	        assert_eq!(dev_bin(&root).unwrap(), root.join("dbg/app"));
453	        let e = release_bin(&root).unwrap_err();
454	        assert!(e.contains("no `build.release-bin`"), "{e}");
455	        let root2 = workspace("nodevbin", "```toml\n[repos]\nwork = \".\"\n```\n");
456	        let e = dev_bin(&root2).unwrap_err();
457	        assert!(e.contains("no `build.dev-bin`"), "{e}");
458	        std::fs::remove_dir_all(&root).ok();
459	        std::fs::remove_dir_all(&root2).ok();
460	    }
461	
462	    /// The commands see the provenance's values. Checked by value, by
463	    /// a script, so a variable inherited from a surrounding run (a
464	    /// `validate` that sets the same names) cannot pass for it.
465	    #[test]
466	    fn the_commands_see_the_provenance() {
467	        let root = workspace("env", "");
468	        std::fs::write(
469	            root.join("check.sh"),
470	            format!(
471	                "[ \"${BUILD_COMMIT_VAR}\" = \"{COMMIT}\" ] && [ \"${BUILD_STATE_VAR}\" = clean ]\n"
472	            ),
473	        )
474	        .unwrap();
475	        std::fs::create_dir_all(root.join("rel/bin")).unwrap();
476	        let params = release(
477	            &root,
478	            vec!["sh check.sh".to_string(), "touch rel/bin/app".to_string()],
479	        );
480	        build(&params).unwrap();
481	        let dev = BuildParams {
482	            label: "build --dev",
483	            key: "build.dev",
484	            commands: vec!["sh check.sh".to_string()],
485	            root: root.clone(),
486	            provenance: Some(prov(SourceState::Clean)),
487	            bin: None,
488	            dry_run: false,
489	        };
490	        build(&dev).unwrap();
491	        std::fs::remove_dir_all(&root).ok();
492	    }
493	
494	    /// A passing release that left its binary passes.
495	    #[test]
496	    fn release_leaves_its_binary() {
497	        let root = workspace("pass", "");
498	        std::fs::create_dir_all(root.join("rel/bin")).unwrap();
499	        build(&release(&root, vec!["touch rel/bin/app".to_string()])).unwrap();
500	        std::fs::remove_dir_all(&root).ok();
501	    }
502	
503	    /// A failed release is an error naming the command.
504	    #[test]
505	    fn failed_release_errors() {
506	        let root = workspace("fail", "");
507	        let e = build(&release(&root, vec!["false".to_string()]))
508	            .unwrap_err()
509	            .to_string();
510	        assert!(e.contains("`false` failed"), "{e}");
511	        std::fs::remove_dir_all(&root).ok();
512	    }
513	
514	    /// A release whose list passes but leaves no binary at
515	    /// `release-bin` is an error.
516	    #[test]
517	    fn release_without_its_binary_errors() {
518	        let root = workspace("nobinary", "");
519	        let e = build(&release(&root, vec!["true".to_string()]))
520	            .unwrap_err()
521	            .to_string();
522	        assert!(e.contains("left no binary"), "{e}");
523	        std::fs::remove_dir_all(&root).ok();
524	    }
525	
526	    /// A dry run prints the list and runs nothing, so a failing
527	    /// command passes and a command that writes leaves nothing.
528	    #[test]
529	    fn a_dry_run_runs_nothing() {
530	        let root = workspace("dry", "");
531	        let mut params = release(&root, vec!["touch ran".to_string(), "false".to_string()]);
532	        params.dry_run = true;
533	        build(&params).unwrap();
534	        assert!(!root.join("ran").exists(), "a dry run ran the list");
535	        assert!(
536	            parse(&["vc-x1", "build", "--dry-run"]).dry_run.value,
537	            "build takes --dry-run"
538	        );
539	        assert!(
540	            parse(&["vc-x1", "build", "--dev", "--dry-run"])
541	                .dry_run
542	                .value
543	        );
544	        std::fs::remove_dir_all(&root).ok();
545	    }
546	
547	    /// The dev build runs its list and checks no binary.
548	    #[test]
549	    fn dev_runs_its_list() {
550	        let root = workspace("dev", "");
551	        let params = BuildParams {
552	            label: "build --dev",
553	            key: "build.dev",
554	            commands: vec!["touch dev-ran".to_string()],
555	            root: root.clone(),
556	            provenance: None,
557	            bin: None,
558	            dry_run: false,
559	        };
560	        build(&params).unwrap();
561	        assert!(root.join("dev-ran").exists());
562	        std::fs::remove_dir_all(&root).ok();
563	    }
564	}
