316	
317	    /// Placeholders fill inside a word, a value with spaces stays one
318	    /// word, a list offered none is as written, any brace that is not
319	    /// a placeholder is literal, and an unknown one is an error naming
320	    /// the ones offered.
321	    #[test]
322	    fn a_list_fills_words_of_its_own() {
323	        let flags = vec!["--profile".to_string(), "release-lto".to_string()];
324	        let none: Vec<String> = vec![];
325	        let vars = [("profile.bin", "target/x/app")];
326	        let lists = [
327	            ("profile.flags", flags.as_slice()),
