181	/// The refusal for a retired `<command>-dev`, naming `<command> --dev`.
182	pub fn retired_dev(command: &str) -> String {
183	    format!(
184	        "{command}-dev: the -dev commands are retired, the dev build is a flag: \
185	         `{command} --dev`"
186	    )
