1	//! A configured command list: a TOML array in the work side's
2	//! config, each element one invocation, run in order from the work
3	//! repo root, stopping at the first failure.
4	//!
5	//! - `[validate] full` and `fast` are run by `validate`,
6	//!   `[build] release` and `dev` by `build` and `build-dev`, and the
7	//!   optional `[install] release` and `dev` by `install` and
8	//!   `install-dev`. Each caller passes its own label, which prefixes
9	//!   every message.
10	//! - Each command is printed before it runs, inherits the terminal,
11	//!   and runs from the root.
12	//! - The first non-zero exit stops the run, naming the command, its
13	//!   status, and where in the list it stopped.
14	//! - An empty or missing list is an error, not a silent pass: a
15	//!   list with nothing to run has done nothing.
16	//! - Elements are split on whitespace into a program and its
17	//!   arguments, with no shell in between, so a command's exit
18	//!   status is exactly the status the run sees.
19	//! - A caller may add environment variables to every command of
20	//!   the list, set on each child alone, never on vc-x1's own
21	//!   process: `build` passes the build's provenance this way.
22	//! - A caller may offer placeholders, `{name}` filled with a value
23	//!   in any word after the split, so a value with spaces stays one
24	//!   argument: `install` offers the resolved keys it reads,
25	//!   `{build.release-bin}` and `{install.release-dir}`. A `{name}`
26	//!   the caller does not offer is an error before anything runs, so
27	//!   a typo never runs as a literal path. A list offered none is
28	//!   taken as written, braces and all.
29	
30	use std::path::Path;
31	
32	use log::info;
33	
34	/// Read `key`'s command list from the work side's config at `root`.
35	///
36	/// Errors, each prefixed by `label` and naming the key, when the
37	/// config is missing or unloadable, the key is absent, the value is
38	/// not a proper array, or the array is empty.
39	pub fn load(root: &Path, key: &str, label: &str) -> Result<Vec<String>, String> {
40	    let (cfg, commands) = read(root, key, label)?;
41	    let commands = commands.ok_or_else(|| {
42	        format!(
43	            "{label}: {}: no `{key}` table. Add one, a TOML array with one command per \
44	                 element (see `vc-x1 config -s work`)",
45	            cfg.path.display()
46	        )
47	    })?;
48	    nonempty(&cfg, key, label, commands)
49	}
50	
51	/// Read `key`'s command list as [`load`] does, an absent key being
52	/// `None` rather than an error, for a list that replaces a built-in
53	/// step when present. A present list is checked as `load` checks it.
54	pub fn load_optional(root: &Path, key: &str, label: &str) -> Result<Option<Vec<String>>, String> {
55	    let (cfg, commands) = read(root, key, label)?;
56	    commands.map(|c| nonempty(&cfg, key, label, c)).transpose()
57	}
58	
59	/// The config at `root` and `key`'s list in it, `None` when absent.
60	fn read(
61	    root: &Path,
62	    key: &str,
63	    label: &str,
64	) -> Result<(crate::config_md::VcConfig, Option<Vec<String>>), String> {
65	    let cfg = crate::config_md::load(root)
66	        .map_err(|e| format!("{label}: {e}"))?
67	        .ok_or_else(|| format!("{label}: no config in '{}'", root.display()))?;
68	    let commands = crate::toml_simple::toml_get_list(&cfg.map, key)
69	        .map_err(|e| format!("{label}: {}: {e}", cfg.path.display()))?;
70	    Ok((cfg, commands))
71	}
72	
73	/// `commands`, or an error when empty: nothing to run is not a pass.
74	fn nonempty(
75	    cfg: &crate::config_md::VcConfig,
76	    key: &str,
77	    label: &str,
78	    commands: Vec<String>,
79	) -> Result<Vec<String>, String> {
80	    if commands.is_empty() {
81	        return Err(format!(
82	            "{label}: {}: `{key}` is empty, nothing to run is not a pass",
83	            cfg.path.display()
84	        ));
85	    }
86	    Ok(commands)
87	}
88	
89	/// Check every placeholder in `commands` is one of `names`, before
90	/// anything runs. `key` names the list and `label` prefixes the error.
91	pub fn check_placeholders(
92	    commands: &[String],
93	    names: &[&str],
94	    key: &str,
95	    label: &str,
96	) -> Result<(), String> {
97	    let vars: Vec<(&str, &str)> = names.iter().map(|n| (*n, "")).collect();
98	    for command in commands {
99	        words(command, &vars).map_err(|e| format!("{label}: `{key}`: {e}"))?;
100	    }
101	    Ok(())
102	}
103	
104	/// Split `command` on whitespace and fill each word's placeholders,
105	/// `{name}` for each `(name, value)` of `vars`: [`expand`] with no
106	/// list-valued placeholders.
107	pub fn words(command: &str, vars: &[(&str, &str)]) -> Result<Vec<String>, String> {
108	    expand(command, vars, &[])
109	}
110	
111	/// Split `command` on whitespace and fill each word's placeholders,
112	/// `{name}` for each `(name, value)` of `vars`, and for each
113	/// `(name, items)` of `lists` a word that is `{name}` alone becomes the
114	/// items, one word each, none for an empty list. A word is split before
115	/// it is filled, so a value with spaces stays one word. With neither
116	/// the words are as written. A `{name}`, a name of letters, digits,
117	/// `.`, `-`, and `_`, offered by neither is an error naming the ones
118	/// offered, a list inside a longer word is an error, since its items
119	/// have no word to share, and any other brace is literal.
120	pub fn expand(
121	    command: &str,
122	    vars: &[(&str, &str)],
123	    lists: &[(&str, &[String])],
124	) -> Result<Vec<String>, String> {
125	    let mut out = Vec::new();
126	    for word in command.split_whitespace() {
127	        let alone = word.strip_prefix('{').and_then(|w| w.strip_suffix('}'));
128	        if let Some((_, items)) = alone.and_then(|name| lists.iter().find(|(n, _)| *n == name)) {
129	            out.extend(items.iter().cloned());
130	        } else if vars.is_empty() && lists.is_empty() {
131	            out.push(word.to_string());
132	        } else {
133	            out.push(fill(word, vars, lists)?);
134	        }
135	    }
136	    Ok(out)
137	}
138	
139	/// Fill one word's placeholders: see [`expand`].
140	fn fill(word: &str, vars: &[(&str, &str)], lists: &[(&str, &[String])]) -> Result<String, String> {
141	    let is_name = |c: char| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_');
142	    let mut out = String::new();
143	    let mut rest = word;
144	    while let Some(open) = rest.find('{') {
145	        out.push_str(&rest[..open]);
146	        let after = &rest[open + 1..];
147	        // OK: no character past the name is a name running to the word's end
148	        let name_len = after.find(|c: char| !is_name(c)).unwrap_or(after.len());
149	        let name = &after[..name_len];
150	        if name.is_empty() || !after[name_len..].starts_with('}') {
151	            out.push('{');
152	            rest = after;
153	            continue;
154	        }
155	        if lists.iter().any(|(n, _)| *n == name) {
156	            return Err(format!(
157	                "`{{{name}}}` is a list, which fills a word of its own, so it stands alone \
158	                 rather than inside `{word}`"
159	            ));
160	        }
161	        let Some((_, value)) = vars.iter().find(|(n, _)| *n == name) else {
162	            let offered: Vec<String> = vars
163	                .iter()
164	                .map(|(n, _)| *n)
165	                .chain(lists.iter().map(|(n, _)| *n))
166	                .map(|n| format!("{{{n}}}"))
167	                .collect();
168	            return Err(format!(
169	                "`{{{name}}}` is not a placeholder here, which offers {}",
170	                offered.join(", ")
171	            ));
172	        };
173	        out.push_str(value);
174	        rest = &after[name_len + 1..];
175	    }
176	    out.push_str(rest);
177	    Ok(out)
178	}
179	
180	/// Run `commands` in order from `root`, printing each before it
181	/// runs, stopping at the first failure. `key` names the list in the
182	/// messages, `label` prefixes them, `env` is added to each command's
183	/// environment, and `vars` are the placeholders offered (see
184	/// [`words`]).
185	pub fn run(
186	    root: &Path,
187	    key: &str,
188	    commands: &[String],
189	    env: &[(&str, &str)],
190	    vars: &[(&str, &str)],
191	    label: &str,
192	) -> Result<(), Box<dyn std::error::Error>> {
193	    let n = commands.len();
194	    for (i, command) in commands.iter().enumerate() {
195	        // The command as it runs, its placeholders filled, so the log
196	        // shows the paths it used.
197	        let shown = match vars {
198	            [] => command.clone(),
199	            _ => words(command, vars)
200	                .map_err(|e| format!("{label}: `{command}`: {e}"))?
201	                .join(" "),
202	        };
203	        let command = &shown;
204	        info!("{label}: [{}/{n}] {command}", i + 1);
205	        let status = run_one(root, &commands[i], env, vars, label)?;
206	        if !status.success() {
207	            return Err(format!(
208	                "{label}: `{command}` failed ({}), stopping at {}/{n} of {key}",
209	                describe_status(status),
210	                i + 1,
211	            )
212	            .into());
213	        }
214	    }
215	    info!("{label}: {n} command(s) passed ({key})");
216	    Ok(())
217	}
218	
219	/// Run one command line from `root`, inheriting stdio and adding
220	/// `env` to its environment, and return its exit status. The line
221	/// is split on whitespace and its placeholders filled from `vars`,
222	/// the first word the program, so no shell sits between vc-x1 and
223	/// the command's own status.
224	pub fn run_one(
225	    root: &Path,
226	    command: &str,
227	    env: &[(&str, &str)],
228	    vars: &[(&str, &str)],
229	    label: &str,
230	) -> Result<std::process::ExitStatus, String> {
231	    let words = words(command, vars).map_err(|e| format!("{label}: `{command}`: {e}"))?;
232	    let Some((program, args)) = words.split_first() else {
233	        return Err(format!("{label}: an empty command element"));
234	    };
235	    // Register entry 5 (clippy.toml): a configured command list,
236	    // `[validate]`'s, `[build]`'s, or `[install]`'s, is run as the
237	    // user would type it, which is the whole job of the commands that
238	    // run one.
239	    #[allow(clippy::disallowed_methods)]
240	    let mut cmd = std::process::Command::new(program);
241	    cmd.args(args).current_dir(root).envs(env.iter().copied());
242	    cmd.status().map_err(|e| {
243	        format!(
244	            "{label}: cannot run `{command}` from '{}': {e}",
245	            root.display()
246	        )
247	    })
248	}
249	
250	/// Render an exit status for the failure message: the code when
251	/// there is one, else the raw status (a signal on Unix).
252	fn describe_status(status: std::process::ExitStatus) -> String {
253	    match status.code() {
254	        Some(code) => format!("exit {code}"),
255	        None => format!("{status}"),
256	    }
257	}
