131	/// Resolve the build, the dev build when `dev`, and its binary. A
132	/// missing config key is an error here, before anything runs.
133	pub fn run_params(
134	    dev: bool,
135	    repo: Option<&Path>,
136	    args: &[OsString],
137	    dry_run: bool,
138	) -> Result<RunParams, String> {
139	    let (label, bin_key) = if dev {
140	        ("run --dev", "build.dev-bin")
141	    } else {
142	        ("run", "build.release-bin")
143	    };
144	    let mut build = build_params(dev, repo)?;
145	    build.dry_run = dry_run;
146	    let bin = if dev {
147	        dev_bin(&build.root)?
148	    } else {
149	        release_bin(&build.root)?
150	    };
151	    let version = crate::install_cmd::manifest_version(&build.root).ok();
152	    Ok(RunParams {
153	        label,
154	        bin_key,
155	        build,
156	        bin,
157	        version,
158	        args: args.to_vec(),
159	        dry_run,
160	    })
161	}
