163	/// Run `run`, with `--dev` or not, for `main`: the binary's exit code is
164	/// vc-x1's, so a failing run fails the same way, and any error
165	/// before it runs is logged and fails.
166	pub fn dispatch(params: Result<RunParams, String>) -> ExitCode {
167	    let params = match params {
168	        Ok(p) => p,
169	        Err(e) => {
170	            error!("{e}");
171	            return ExitCode::FAILURE;
172	        }
173	    };
174	    crate::bm_track("enter", params.label);
175	    let code = match run(&params) {
176	        Ok(code) => exit_code(code),
177	        Err(e) => {
178	            error!("{e}");
179	            ExitCode::FAILURE
180	        }
181	    };
182	    crate::bm_track("exit ", params.label);
183	    code
184	}
185	
186	/// The process exit code for a binary's `code`.
187	fn exit_code(code: i32) -> ExitCode {
188	    // OK: a code outside 0..=255, which no Unix exit status is, is a failure
189	    ExitCode::from(u8::try_from(code).unwrap_or(1))
190	}
191	
192	/// Build, check the binary, and run it with the arguments, returning
193	/// its exit code. A dry run prints the build's list and the command,
194	/// and returns 0.
195	pub fn run(params: &RunParams) -> Result<i32, Box<dyn std::error::Error>> {
196	    debug!("{}: entry params={params:?}", params.label);
197	    crate::build_cmd::build(&params.build)?;
198	    let shown = shown_command(&params.bin, &params.args);
199	    if params.dry_run {
200	        info!("{}: [dry-run] would run {shown}", params.label);
201	        return Ok(0);
202	    }
203	    if !params.bin.is_file() {
204	        return Err(format!(
205	            "{}: no binary at '{}' after the build: check `{}`",
206	            params.label,
207	            params.bin.display(),
208	            params.bin_key
209	        )
210	        .into());
211	    }
212	    let reported = crate::install_cmd::run_version(&params.bin)
213	        .as_deref()
214	        .and_then(crate::install_cmd::parse_reported);
215	    if let Some(note) = version_note(
216	        reported.as_ref().map(|r| r.version.as_str()),
217	        params.version.as_deref(),
218	    ) {
219	        warn!(
220	            "{}: '{}' {note}: check `{}`",
221	            params.label,
222	            params.bin.display(),
223	            params.bin_key
224	        );
225	    }
226	    info!("{}: {shown}", params.label);
227	    // Register entry 7 (clippy.toml): run and run-dev run the
228	    // workspace's build, which is the whole job of the command.
229	    #[allow(clippy::disallowed_methods)]
230	    let status = std::process::Command::new(&params.bin)
231	        .args(&params.args)
232	        .status()
233	        .map_err(|e| {
234	            format!(
235	                "{}: cannot run '{}': {e}",
236	                params.label,
237	                params.bin.display()
238	            )
239	        })?;
240	    match status.code() {
241	        Some(code) => Ok(code),
242	        None => Err(format!("{}: '{}' {status}", params.label, params.bin.display()).into()),
243	    }
244	}
