256	/// The warning for a binary reporting `reported` when the manifest
257	/// says `manifest`, `None` when they agree or either is unknown.
258	fn version_note(reported: Option<&str>, manifest: Option<&str>) -> Option<String> {
259	    let (reported, manifest) = (reported?, manifest?);
260	    (reported != manifest).then(|| format!("reports {reported}, the manifest's is {manifest}"))
261	}
