263	/// What a completion forward asks: the build whose binary answers,
264	/// the workspace `-R` named, the words it is given, its own name
265	/// first, and the cursor's index among them when the shell gave one.
266	#[derive(Debug, PartialEq, Eq)]
267	pub struct Forward {
268	    /// `run --dev`'s dev build rather than `run`'s release.
269	    pub dev: bool,
270	    /// The workspace `-R` named, else the current directory's.
271	    pub repo: Option<PathBuf>,
272	    /// The words for the binary, the first standing for its name.
273	    pub words: Vec<String>,
274	    /// The cursor's index in `words`, when the shell passed one.
275	    pub index: Option<usize>,
276	}
277	
278	/// Plan a completion forward from the words a shell passes, the
279	/// program's name first, and the cursor's index among them, or
280	/// `None` when the words are not `run`'s arguments and clap completes
281	/// them itself.
282	///
283	/// - The subcommand is the first word after vc-x1's own flags, and
284	///   only `run` is forwarded. Any other subcommand is clap's.
285	/// - The subcommand's own options, `--dev`, `-d`, `--dry-run`, `-R
286	///   DIR`, `--repo DIR`, and `--repo=DIR`, are skipped, `--dev`
287	///   choosing the dev build, and `--` ends them. A word
288	///   at the cursor that starts with `-` before any argument is
289	///   clap's, so `run --d<TAB>` offers `--dry-run`.
290	/// - The cursor on the subcommand or its options is clap's too, so
291	///   only the arguments are forwarded, with the index shifted to
292	///   match.
293	pub fn plan_forward(words: &[String], index: Option<usize>) -> Option<Forward> {
294	    // OK: with no index the shell completes the last word
295	    let cursor = index.unwrap_or(words.len().saturating_sub(1));
296	    let sub = words
297	        .iter()
298	        .enumerate()
299	        .skip(1)
300	        .find(|(_, w)| !w.starts_with('-'))
301	        .map(|(i, _)| i)?;
302	    if words[sub] != "run" {
303	        return None;
304	    }
305	    let mut dev = false;
306	    let mut repo = None;
307	    let mut i = sub + 1;
308	    while i < words.len() && i < cursor {
309	        let w = words[i].as_str();
310	        if w == "--" {
311	            i += 1;
312	            break;
313	        }
314	        if w == "--dry-run" {
315	            i += 1;
316	        } else if w == "--dev" || w == "-d" {
317	            dev = true;
318	            i += 1;
319	        } else if w == "-R" || w == "--repo" {
320	            repo = words.get(i + 1).map(PathBuf::from);
321	            i += 2;
322	        } else if let Some(dir) = w.strip_prefix("--repo=") {
323	            repo = Some(PathBuf::from(dir));
324	            i += 1;
325	        } else {
326	            break;
327	        }
328	    }
329	    if cursor < i || (cursor == i && words[i].starts_with('-') && words[i - 1] != "--") {
330	        return None;
331	    }
332	    let mut forwarded = vec![words[0].clone()];
333	    forwarded.extend(words[i..].iter().cloned());
334	    Some(Forward {
335	        dev,
336	        repo,
337	        words: forwarded,
338	        index: index.map(|n| n - (i - 1)),
339	    })
340	}
341	
342	/// Forward a completion request for `run`'s arguments
343	/// to the binary it would run, and exit with its answer. Called by
344	/// `main` before clap's completion, which it leaves alone for every
345	/// other request.
346	///
347	/// A shell asks by running `COMPLETE=<shell> vc-x1 -- <words>` with
348	/// the cursor in `_CLAP_COMPLETE_INDEX` for most shells. The binary
349	/// is asked the same way, `COMPLETE` and the shell's other variables
350	/// inherited and the index shifted, so it answers in the protocol
351	/// the shell reads. Its config is the workspace's the shell is in, or
352	/// `-R`'s, and it is never built: no binary, or none that answers,
353	/// prints nothing.
354	pub fn forward_completion() {
355	    if std::env::var_os("COMPLETE").is_none_or(|v| v.is_empty() || v == "0") {
356	        return;
357	    }
358	    let args: Vec<String> = std::env::args().collect();
359	    if args.get(1).map(String::as_str) != Some("--") {
360	        return;
361	    }
362	    let index = std::env::var("_CLAP_COMPLETE_INDEX")
363	        .ok()
364	        .and_then(|i| i.parse().ok());
365	    let Some(plan) = plan_forward(&args[2..], index) else {
366	        return;
367	    };
368	    let code = forward(&plan);
369	    std::process::exit(code);
370	}
371	
372	/// Ask the binary `plan` names, returning its exit code, 0 when there
373	/// is none to ask.
374	fn forward(plan: &Forward) -> i32 {
375	    let root = match &plan.repo {
376	        Some(p) => crate::common::find_workspace_root_from(p),
377	        None => crate::common::find_workspace_root(),
378	    };
379	    let Some(root) = root else {
380	        return 0;
381	    };
382	    let bin = if plan.dev {
383	        dev_bin(&root)
384	    } else {
385	        release_bin(&root)
386	    };
387	    let Ok(bin) = bin else {
388	        return 0;
389	    };
390	    if !bin.is_file() {
391	        return 0;
392	    }
393	    // Register entry 7 (clippy.toml): the completion forward asks the
394	    // workspace's build, in clap's completion mode, for its own words.
395	    #[allow(clippy::disallowed_methods)]
396	    let mut cmd = std::process::Command::new(&bin);
397	    cmd.arg("--").args(&plan.words);
398	    if let Some(index) = plan.index {
399	        cmd.env("_CLAP_COMPLETE_INDEX", index.to_string());
400	    }
401	    match cmd.status() {
402	        // OK: a binary killed by a signal answered nothing
403	        Ok(status) => status.code().unwrap_or(0),
404	        Err(_) => 0,
405	    }
406	}
