435	            Some(Commands::Run(a)) => a,
436	            _ => panic!("expected Run"),
437	        };
438	        let a = run(&["vc-x1", "run", "--", "-V"]);
439	        assert_eq!(a.args, [OsString::from("-V")]);
440	        let a = run(&["vc-x1", "run", "bench", "--fast", "-x", "--", "y"]);
441	        assert_eq!(a.args, ["bench", "--fast", "-x", "--", "y"]);
442	        let a = run(&["vc-x1", "run", "--dry-run", "-R", "w", "x"]);
443	        assert!(a.dry_run.value);
444	        assert_eq!(
445	            (a.repo, a.args),
446	            (Some(PathBuf::from("w")), vec![OsString::from("x")])
447	        );
448	        let cli = Cli::try_parse_from(["vc-x1", "run", "-V"]).unwrap();
449	        assert_eq!(cli.version, 1, "-V before the arguments is vc-x1's");
450	        let a = run(&["vc-x1", "run", "--dev", "--", "-V"]);
451	        assert!(a.dev);
452	        assert_eq!(a.args, [OsString::from("-V")]);
453	        let a = run(&["vc-x1", "run", "x", "--dev"]);
454	        assert!(!a.dev, "--dev after an argument is the binary's");
455	        match Cli::try_parse_from(["vc-x1", "run-dev", "--", "-V"])
456	            .unwrap()
457	            .command
458	        {
459	            Some(Commands::RunDev(a)) => {
460	                let err = RunParams::try_from(&a).unwrap_err();
461	                assert!(err.ends_with("`run --dev`"), "{err}");
462	            }
463	            _ => panic!("expected RunDev"),
464	        }
465	    }
466	
467	    /// A version other than the manifest's is named, and agreement or
468	    /// an unknown either side says nothing.
469	    #[test]
470	    fn version_note_forms() {
471	        assert_eq!(
472	            version_note(Some("0.1.0"), Some("0.2.0")).as_deref(),
473	            Some("reports 0.1.0, the manifest's is 0.2.0")
474	        );
475	        assert_eq!(version_note(Some("0.2.0"), Some("0.2.0")), None);
476	        assert_eq!(version_note(None, Some("0.2.0")), None);
477	        assert_eq!(version_note(Some("0.2.0"), None), None);
478	    }
479	
480	    /// The binary runs with the arguments untouched, in the current
481	    /// directory, after the build, and its exit code is returned; a
482	    /// dry run builds nothing and runs nothing.
483	    #[test]
484	    fn the_binary_runs_with_its_arguments() {
485	        let dir = tempdir("bin");
486	        let out = dir.join("args.txt");
487	        let bin = dir.join("app");
488	        std::fs::write(
489	            &bin,
490	            format!(
491	                "#!/bin/sh\nprintf '%s|' \"$@\" > '{}'\nexit 3\n",
492	                out.display()
493	            ),
494	        )
495	        .unwrap();
496	        use std::os::unix::fs::PermissionsExt;
497	        std::fs::set_permissions(&bin, std::fs::Permissions::from_mode(0o755)).unwrap();
498	        let mut params = RunParams {
499	            label: "run --dev",
500	            bin_key: "build.dev-bin",
501	            build: BuildParams {
502	                label: "build --dev",
503	                key: "build.dev",
504	                commands: vec!["touch built".to_string()],
505	                root: dir.clone(),
506	                provenance: None,
507	                bin: None,
508	                dry_run: true,
509	            },
510	            bin: bin.clone(),
511	            version: None,
512	            args: vec!["a b".into(), "-x".into()],
513	            dry_run: true,
514	        };
515	        assert_eq!(run(&params).unwrap(), 0);
516	        assert!(
517	            !out.exists() && !dir.join("built").exists(),
518	            "a dry run ran"
519	        );
520	        params.dry_run = false;
521	        params.build.dry_run = false;
522	        assert_eq!(run(&params).unwrap(), 3, "the binary's exit code");
523	        assert!(dir.join("built").exists(), "the build ran first");
524	        assert_eq!(std::fs::read_to_string(&out).unwrap(), "a b|-x|");
525	        params.bin = dir.join("absent");
526	        let e = run(&params).unwrap_err().to_string();
527	        assert!(
528	            e.contains("no binary at") && e.contains("build.dev-bin"),
529	            "{e}"
530	        );
531	        std::fs::remove_dir_all(&dir).ok();
532	    }
533	
534	    /// Only `run`'s arguments are forwarded, its
535	    /// own options skipped and the index shifted, and the cursor on
536	    /// the subcommand, its options, or a flag before any argument is
537	    /// clap's.
538	    #[test]
539	    fn plan_forward_forms() {
540	        let p = plan_forward(&w("vc-x1 run --dev run zcr"), Some(4)).unwrap();
541	        assert_eq!(
542	            p,
543	            Forward {
544	                dev: true,
545	                repo: None,
546	                words: w("vc-x1 run zcr"),
547	                index: Some(2),
548	            }
549	        );
550	        let p = plan_forward(&w("vc-x1 -v run --dry-run -R ../w -- --fast "), Some(7)).unwrap();
551	        assert!(!p.dev);
552	        assert_eq!(p.repo, Some(PathBuf::from("../w")));
553	        assert_eq!((p.words, p.index), (w("vc-x1 --fast "), Some(1)));
554	        let p = plan_forward(&w("vc-x1 run --repo=x a"), None).unwrap();
555	        assert_eq!(
556	            (p.repo, p.words, p.index),
557	            (Some(PathBuf::from("x")), w("vc-x1 a"), None)
558	        );
559	        assert_eq!(
560	            plan_forward(&w("vc-x1 run-dev run"), Some(2)),
561	            None,
562	            "the retired run-dev is clap's, which refuses it"
563	        );
564	        assert_eq!(
565	            plan_forward(&w("vc-x1 run --d"), Some(2)),
566	            None,
567	            "run's own flag"
568	        );
569	        assert_eq!(
570	            plan_forward(&w("vc-x1 run -R "), Some(3)),
571	            None,
572	            "-R's value"
573	        );
574	        assert_eq!(
575	            plan_forward(&w("vc-x1 build x"), Some(2)),
576	            None,
577	            "another subcommand"
578	        );
579	        assert_eq!(
580	            plan_forward(&w("vc-x1 run a --d"), Some(3)).unwrap().words,
581	            w("vc-x1 a --d")
582	        );
583	    }
584	
585	    /// A forward with no workspace, or no binary, answers nothing.
586	    #[test]
587	    fn a_forward_with_nothing_to_ask_answers_nothing() {
588	        let dir = tempdir("noforward");
589	        let plan = Forward {
590	            dev: true,
591	            repo: Some(dir.clone()),
592	            words: w("x a"),
593	            index: Some(1),
594	        };
595	        assert_eq!(forward(&plan), 0, "no workspace");
596	        std::fs::write(
597	            dir.join(".vc-config.md"),
598	            "```toml\n[repos]\nwork = \".\"\n[build]\ndev-bin = \"absent\"\n```\n",
599	        )
600	        .unwrap();
601	        assert_eq!(forward(&plan), 0, "no binary");
602	        std::fs::remove_dir_all(&dir).ok();
603	    }
