//! The `run` subcommand: build the release, or with `--dev` the dev
//! build, then run its binary with the given arguments, as
//! `cargo run` builds before it runs. It never touches the PATH, so a
//! build is tried before `install` copies it. The dev run was
//! `run-dev`, kept hidden to be refused naming `run --dev`.
//!
//! - `vc-x1 run` runs `[build] release` and then
//!   `[build] release-bin`, and `vc-x1 run --dev` runs `[build] dev`
//!   and then `[build] dev-bin`, through `build`'s own code, so what
//!   runs is always the current code. `--dev` comes before the
//!   arguments, which are the binary's.
//! - The arguments go to the binary untouched. One that starts with
//!   `-` comes after `--`, `vc-x1 run -- -V`, as with `cargo run`,
//!   since vc-x1's own flags, `-V` among them, are read first.
//! - The binary runs in the current directory, with the terminal, and
//!   its exit code is vc-x1's, so a failing run fails the same way.
//! - Before it runs, its `-V` is read, and a version other than the
//!   manifest's is a warning naming the key: the build passed but
//!   left an older binary where the config says. Output with no
//!   version is passed over quietly, since another project's binary
//!   may print none.
//! - `--dry-run` prints the build's list and the command, and runs
//!   nothing.
//! - Completion is forwarded: the words after `run` and its own
//!   options are completed by the binary it would run, asked in clap's
//!   completion mode, so `vc-x1 run --dev run <TAB>` offers the dev
//!   build's own words. The binary is asked as it stands and never built, and
//!   one that answers nothing, or is not there, offers nothing. See
//!   [`forward_completion`].

use std::ffi::OsString;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use clap::Args;
use log::{debug, error, info, warn};

use crate::build_cmd::{BuildParams, build_params, dev_bin, release_bin};
use crate::options_flags::dry_run::DryRunFlag;

/// Build the release, or with `--dev` the dev build, then run it.
#[derive(Args, Debug)]
pub struct RunArgs {
    /// Build and run the dev build, `[build] dev` and `dev-bin`,
    /// instead of the release, given before the arguments
    #[arg(short = 'd', long)]
    pub dev: bool,

    #[command(flatten)]
    pub dry_run: DryRunFlag,

    /// Workspace to run from [default: the workspace containing the
    /// current directory]
    #[arg(short = 'R', long, value_name = "DIR")]
    pub repo: Option<PathBuf>,

    /// Arguments for the release build, after `--` when the first
    /// starts with `-`
    #[arg(
        trailing_var_arg = true,
        allow_hyphen_values = true,
        value_name = "ARGS"
    )]
    pub args: Vec<OsString>,
}

/// Retired: `run-dev`, now `run --dev`, refused naming it. Its flags
/// are kept so an old invocation parses and is told the fix.
#[derive(Args, Debug)]
pub struct RunDevArgs {
    #[command(flatten)]
    pub dry_run: DryRunFlag,

    /// Workspace to run from [default: the workspace containing the
    /// current directory]
    #[arg(short = 'R', long, value_name = "DIR")]
    pub repo: Option<PathBuf>,

    /// Arguments for the dev build, after `--` when the first starts
    /// with `-`
    #[arg(
        trailing_var_arg = true,
        allow_hyphen_values = true,
        value_name = "ARGS"
    )]
    pub args: Vec<OsString>,
}

/// Per-invocation run inputs: the build to run first, its binary, the
/// manifest's version to check it against, and the arguments.
#[derive(Debug)]
pub struct RunParams {
    /// `run` or `run --dev`, prefixing the run's messages.
    pub label: &'static str,
    /// `build.release-bin` or `build.dev-bin`, for a message to point
    /// at.
    pub bin_key: &'static str,
    /// The build, `vc-x1 build`'s or `vc-x1 build-dev`'s, a dry run
    /// when this one is.
    pub build: BuildParams,
    /// The binary to run.
    pub bin: PathBuf,
    /// The manifest's version, `None` when the root has no
    /// `Cargo.toml` to read it from.
    pub version: Option<String>,
    /// The arguments, passed untouched.
    pub args: Vec<OsString>,
    /// Print the build's list and the command, and run nothing.
    pub dry_run: bool,
}

impl TryFrom<&RunArgs> for RunParams {
    type Error = String;

    /// The release, or the dev build with `--dev`: see
    /// [`run_params`].
    fn try_from(a: &RunArgs) -> Result<Self, String> {
        run_params(a.dev, a.repo.as_deref(), &a.args, a.dry_run.value)
    }
}

impl TryFrom<&RunDevArgs> for RunParams {
    type Error = String;

    /// Refused: `run-dev` is `run --dev`.
    fn try_from(_: &RunDevArgs) -> Result<Self, String> {
        Err(crate::build_cmd::retired_dev("run"))
    }
}

/// Resolve the build, the dev build when `dev`, and its binary. A
/// missing config key is an error here, before anything runs.
pub fn run_params(
    dev: bool,
    repo: Option<&Path>,
    args: &[OsString],
    dry_run: bool,
) -> Result<RunParams, String> {
    let (label, bin_key) = if dev {
        ("run --dev", "build.dev-bin")
    } else {
        ("run", "build.release-bin")
    };
    let mut build = build_params(dev, repo)?;
    build.dry_run = dry_run;
    let bin = if dev {
        dev_bin(&build.root)?
    } else {
        release_bin(&build.root)?
    };
    let version = crate::install_cmd::manifest_version(&build.root).ok();
    Ok(RunParams {
        label,
        bin_key,
        build,
        bin,
        version,
        args: args.to_vec(),
        dry_run,
    })
}

/// Run `run`, with `--dev` or not, for `main`: the binary's exit code is
/// vc-x1's, so a failing run fails the same way, and any error
/// before it runs is logged and fails.
pub fn dispatch(params: Result<RunParams, String>) -> ExitCode {
    let params = match params {
        Ok(p) => p,
        Err(e) => {
            error!("{e}");
            return ExitCode::FAILURE;
        }
    };
    crate::bm_track("enter", params.label);
    let code = match run(&params) {
        Ok(code) => exit_code(code),
        Err(e) => {
            error!("{e}");
            ExitCode::FAILURE
        }
    };
    crate::bm_track("exit ", params.label);
    code
}

/// The process exit code for a binary's `code`.
fn exit_code(code: i32) -> ExitCode {
    // OK: a code outside 0..=255, which no Unix exit status is, is a failure
    ExitCode::from(u8::try_from(code).unwrap_or(1))
}

/// Build, check the binary, and run it with the arguments, returning
/// its exit code. A dry run prints the build's list and the command,
/// and returns 0.
pub fn run(params: &RunParams) -> Result<i32, Box<dyn std::error::Error>> {
    debug!("{}: entry params={params:?}", params.label);
    crate::build_cmd::build(&params.build)?;
    let shown = shown_command(&params.bin, &params.args);
    if params.dry_run {
        info!("{}: [dry-run] would run {shown}", params.label);
        return Ok(0);
    }
    if !params.bin.is_file() {
        return Err(format!(
            "{}: no binary at '{}' after the build: check `{}`",
            params.label,
            params.bin.display(),
            params.bin_key
        )
        .into());
    }
    let reported = crate::install_cmd::run_version(&params.bin)
        .as_deref()
        .and_then(crate::install_cmd::parse_reported);
    if let Some(note) = version_note(
        reported.as_ref().map(|r| r.version.as_str()),
        params.version.as_deref(),
    ) {
        warn!(
            "{}: '{}' {note}: check `{}`",
            params.label,
            params.bin.display(),
            params.bin_key
        );
    }
    info!("{}: {shown}", params.label);
    // Register entry 7 (clippy.toml): run and run-dev run the
    // workspace's build, which is the whole job of the command.
    #[allow(clippy::disallowed_methods)]
    let status = std::process::Command::new(&params.bin)
        .args(&params.args)
        .status()
        .map_err(|e| {
            format!(
                "{}: cannot run '{}': {e}",
                params.label,
                params.bin.display()
            )
        })?;
    match status.code() {
        Some(code) => Ok(code),
        None => Err(format!("{}: '{}' {status}", params.label, params.bin.display()).into()),
    }
}

/// The command as the log shows it: the binary and its arguments.
fn shown_command(bin: &Path, args: &[OsString]) -> String {
    let mut out = format!("'{}'", bin.display());
    for a in args {
        out.push(' ');
        out.push_str(&a.to_string_lossy());
    }
    out
}

/// The warning for a binary reporting `reported` when the manifest
/// says `manifest`, `None` when they agree or either is unknown.
fn version_note(reported: Option<&str>, manifest: Option<&str>) -> Option<String> {
    let (reported, manifest) = (reported?, manifest?);
    (reported != manifest).then(|| format!("reports {reported}, the manifest's is {manifest}"))
}

/// What a completion forward asks: the build whose binary answers,
/// the workspace `-R` named, the words it is given, its own name
/// first, and the cursor's index among them when the shell gave one.
#[derive(Debug, PartialEq, Eq)]
pub struct Forward {
    /// `run --dev`'s dev build rather than `run`'s release.
    pub dev: bool,
    /// The workspace `-R` named, else the current directory's.
    pub repo: Option<PathBuf>,
    /// The words for the binary, the first standing for its name.
    pub words: Vec<String>,
    /// The cursor's index in `words`, when the shell passed one.
    pub index: Option<usize>,
}

/// Plan a completion forward from the words a shell passes, the
/// program's name first, and the cursor's index among them, or
/// `None` when the words are not `run`'s arguments and clap completes
/// them itself.
///
/// - The subcommand is the first word after vc-x1's own flags, and
///   only `run` is forwarded. Any other subcommand is clap's.
/// - The subcommand's own options, `--dev`, `-d`, `--dry-run`, `-R
///   DIR`, `--repo DIR`, and `--repo=DIR`, are skipped, `--dev`
///   choosing the dev build, and `--` ends them. A word
///   at the cursor that starts with `-` before any argument is
///   clap's, so `run --d<TAB>` offers `--dry-run`.
/// - The cursor on the subcommand or its options is clap's too, so
///   only the arguments are forwarded, with the index shifted to
///   match.
pub fn plan_forward(words: &[String], index: Option<usize>) -> Option<Forward> {
    // OK: with no index the shell completes the last word
    let cursor = index.unwrap_or(words.len().saturating_sub(1));
    let sub = words
        .iter()
        .enumerate()
        .skip(1)
        .find(|(_, w)| !w.starts_with('-'))
        .map(|(i, _)| i)?;
    if words[sub] != "run" {
        return None;
    }
    let mut dev = false;
    let mut repo = None;
    let mut i = sub + 1;
    while i < words.len() && i < cursor {
        let w = words[i].as_str();
        if w == "--" {
            i += 1;
            break;
        }
        if w == "--dry-run" {
            i += 1;
        } else if w == "--dev" || w == "-d" {
            dev = true;
            i += 1;
        } else if w == "-R" || w == "--repo" {
            repo = words.get(i + 1).map(PathBuf::from);
            i += 2;
        } else if let Some(dir) = w.strip_prefix("--repo=") {
            repo = Some(PathBuf::from(dir));
            i += 1;
        } else {
            break;
        }
    }
    if cursor < i || (cursor == i && words[i].starts_with('-') && words[i - 1] != "--") {
        return None;
    }
    let mut forwarded = vec![words[0].clone()];
    forwarded.extend(words[i..].iter().cloned());
    Some(Forward {
        dev,
        repo,
        words: forwarded,
        index: index.map(|n| n - (i - 1)),
    })
}

/// Forward a completion request for `run`'s arguments
/// to the binary it would run, and exit with its answer. Called by
/// `main` before clap's completion, which it leaves alone for every
/// other request.
///
/// A shell asks by running `COMPLETE=<shell> vc-x1 -- <words>` with
/// the cursor in `_CLAP_COMPLETE_INDEX` for most shells. The binary
/// is asked the same way, `COMPLETE` and the shell's other variables
/// inherited and the index shifted, so it answers in the protocol
/// the shell reads. Its config is the workspace's the shell is in, or
/// `-R`'s, and it is never built: no binary, or none that answers,
/// prints nothing.
pub fn forward_completion() {
    if std::env::var_os("COMPLETE").is_none_or(|v| v.is_empty() || v == "0") {
        return;
    }
    let args: Vec<String> = std::env::args().collect();
    if args.get(1).map(String::as_str) != Some("--") {
        return;
    }
    let index = std::env::var("_CLAP_COMPLETE_INDEX")
        .ok()
        .and_then(|i| i.parse().ok());
    let Some(plan) = plan_forward(&args[2..], index) else {
        return;
    };
    let code = forward(&plan);
    std::process::exit(code);
}

/// Ask the binary `plan` names, returning its exit code, 0 when there
/// is none to ask.
fn forward(plan: &Forward) -> i32 {
    let root = match &plan.repo {
        Some(p) => crate::common::find_workspace_root_from(p),
        None => crate::common::find_workspace_root(),
    };
    let Some(root) = root else {
        return 0;
    };
    let bin = if plan.dev {
        dev_bin(&root)
    } else {
        release_bin(&root)
    };
    let Ok(bin) = bin else {
        return 0;
    };
    if !bin.is_file() {
        return 0;
    }
    // Register entry 7 (clippy.toml): the completion forward asks the
    // workspace's build, in clap's completion mode, for its own words.
    #[allow(clippy::disallowed_methods)]
    let mut cmd = std::process::Command::new(&bin);
    cmd.arg("--").args(&plan.words);
    if let Some(index) = plan.index {
        cmd.env("_CLAP_COMPLETE_INDEX", index.to_string());
    }
    match cmd.status() {
        // OK: a binary killed by a signal answered nothing
        Ok(status) => status.code().unwrap_or(0),
        Err(_) => 0,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{Cli, Commands};
    use clap::Parser;

    fn w(s: &str) -> Vec<String> {
        s.split(' ').map(str::to_string).collect()
    }

    /// Unique tempdir.
    fn tempdir(tag: &str) -> PathBuf {
        let ts = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let dir = std::env::temp_dir().join(format!("vc-x1-run-{tag}-{ts}"));
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    /// The arguments pass through untouched, a hyphen one after `--`
    /// or after the first argument, and vc-x1's own `-V` before them
    /// is vc-x1's.
    #[test]
    fn flags_parse() {
        let run = |args: &[&str]| match Cli::try_parse_from(args).unwrap().command {
            Some(Commands::Run(a)) => a,
            _ => panic!("expected Run"),
        };
        let a = run(&["vc-x1", "run", "--", "-V"]);
        assert_eq!(a.args, [OsString::from("-V")]);
        let a = run(&["vc-x1", "run", "bench", "--fast", "-x", "--", "y"]);
        assert_eq!(a.args, ["bench", "--fast", "-x", "--", "y"]);
        let a = run(&["vc-x1", "run", "--dry-run", "-R", "w", "x"]);
        assert!(a.dry_run.value);
        assert_eq!(
            (a.repo, a.args),
            (Some(PathBuf::from("w")), vec![OsString::from("x")])
        );
        let cli = Cli::try_parse_from(["vc-x1", "run", "-V"]).unwrap();
        assert_eq!(cli.version, 1, "-V before the arguments is vc-x1's");
        let a = run(&["vc-x1", "run", "--dev", "--", "-V"]);
        assert!(a.dev);
        assert_eq!(a.args, [OsString::from("-V")]);
        let a = run(&["vc-x1", "run", "x", "--dev"]);
        assert!(!a.dev, "--dev after an argument is the binary's");
        match Cli::try_parse_from(["vc-x1", "run-dev", "--", "-V"])
            .unwrap()
            .command
        {
            Some(Commands::RunDev(a)) => {
                let err = RunParams::try_from(&a).unwrap_err();
                assert!(err.ends_with("`run --dev`"), "{err}");
            }
            _ => panic!("expected RunDev"),
        }
    }

    /// A version other than the manifest's is named, and agreement or
    /// an unknown either side says nothing.
    #[test]
    fn version_note_forms() {
        assert_eq!(
            version_note(Some("0.1.0"), Some("0.2.0")).as_deref(),
            Some("reports 0.1.0, the manifest's is 0.2.0")
        );
        assert_eq!(version_note(Some("0.2.0"), Some("0.2.0")), None);
        assert_eq!(version_note(None, Some("0.2.0")), None);
        assert_eq!(version_note(Some("0.2.0"), None), None);
    }

    /// The binary runs with the arguments untouched, in the current
    /// directory, after the build, and its exit code is returned; a
    /// dry run builds nothing and runs nothing.
    #[test]
    fn the_binary_runs_with_its_arguments() {
        let dir = tempdir("bin");
        let out = dir.join("args.txt");
        let bin = dir.join("app");
        std::fs::write(
            &bin,
            format!(
                "#!/bin/sh\nprintf '%s|' \"$@\" > '{}'\nexit 3\n",
                out.display()
            ),
        )
        .unwrap();
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&bin, std::fs::Permissions::from_mode(0o755)).unwrap();
        let mut params = RunParams {
            label: "run --dev",
            bin_key: "build.dev-bin",
            build: BuildParams {
                label: "build --dev",
                key: "build.dev",
                commands: vec!["touch built".to_string()],
                root: dir.clone(),
                provenance: None,
                bin: None,
                dry_run: true,
            },
            bin: bin.clone(),
            version: None,
            args: vec!["a b".into(), "-x".into()],
            dry_run: true,
        };
        assert_eq!(run(&params).unwrap(), 0);
        assert!(
            !out.exists() && !dir.join("built").exists(),
            "a dry run ran"
        );
        params.dry_run = false;
        params.build.dry_run = false;
        assert_eq!(run(&params).unwrap(), 3, "the binary's exit code");
        assert!(dir.join("built").exists(), "the build ran first");
        assert_eq!(std::fs::read_to_string(&out).unwrap(), "a b|-x|");
        params.bin = dir.join("absent");
        let e = run(&params).unwrap_err().to_string();
        assert!(
            e.contains("no binary at") && e.contains("build.dev-bin"),
            "{e}"
        );
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Only `run`'s arguments are forwarded, its
    /// own options skipped and the index shifted, and the cursor on
    /// the subcommand, its options, or a flag before any argument is
    /// clap's.
    #[test]
    fn plan_forward_forms() {
        let p = plan_forward(&w("vc-x1 run --dev run zcr"), Some(4)).unwrap();
        assert_eq!(
            p,
            Forward {
                dev: true,
                repo: None,
                words: w("vc-x1 run zcr"),
                index: Some(2),
            }
        );
        let p = plan_forward(&w("vc-x1 -v run --dry-run -R ../w -- --fast "), Some(7)).unwrap();
        assert!(!p.dev);
        assert_eq!(p.repo, Some(PathBuf::from("../w")));
        assert_eq!((p.words, p.index), (w("vc-x1 --fast "), Some(1)));
        let p = plan_forward(&w("vc-x1 run --repo=x a"), None).unwrap();
        assert_eq!(
            (p.repo, p.words, p.index),
            (Some(PathBuf::from("x")), w("vc-x1 a"), None)
        );
        assert_eq!(
            plan_forward(&w("vc-x1 run-dev run"), Some(2)),
            None,
            "the retired run-dev is clap's, which refuses it"
        );
        assert_eq!(
            plan_forward(&w("vc-x1 run --d"), Some(2)),
            None,
            "run's own flag"
        );
        assert_eq!(
            plan_forward(&w("vc-x1 run -R "), Some(3)),
            None,
            "-R's value"
        );
        assert_eq!(
            plan_forward(&w("vc-x1 build x"), Some(2)),
            None,
            "another subcommand"
        );
        assert_eq!(
            plan_forward(&w("vc-x1 run a --d"), Some(3)).unwrap().words,
            w("vc-x1 a --d")
        );
    }

    /// A forward with no workspace, or no binary, answers nothing.
    #[test]
    fn a_forward_with_nothing_to_ask_answers_nothing() {
        let dir = tempdir("noforward");
        let plan = Forward {
            dev: true,
            repo: Some(dir.clone()),
            words: w("x a"),
            index: Some(1),
        };
        assert_eq!(forward(&plan), 0, "no workspace");
        std::fs::write(
            dir.join(".vc-config.md"),
            "```toml\n[repos]\nwork = \".\"\n[build]\ndev-bin = \"absent\"\n```\n",
        )
        .unwrap();
        assert_eq!(forward(&plan), 0, "no binary");
        std::fs::remove_dir_all(&dir).ok();
    }
}

//! The `install` subcommand: build the release, or with `--dev` the
//! dev build, then copy it into the install directory, the command
//! that touches the PATH, after reporting what it copies. The dev
//! install was `install-dev`, kept hidden to be refused naming
//! `install --dev`.
//!
//! - `install` runs `[build] release` first, exactly as `vc-x1 build`
//!   does, and `install --dev` runs `[build] dev` as `vc-x1 build
//!   --dev` does. Cargo rebuilds only what changed, so with nothing changed
//!   the binary already tested is the one copied, and a missing or
//!   stale one is built rather than refused.
//! - The binary is `[build] release-bin` or `[build] dev-bin`. The
//!   destination is the one directory `[install] release-dir` or
//!   `dev-dir` names, `~` expanded, so the committed value fits every
//!   machine. The release keeps its file name there, and the dev build
//!   gets `-dev` appended, `vc-x1-dev`, so the two may share a
//!   directory and sit side by side on the PATH. `$PATH` is not
//!   searched.
//! - The report says what is being copied: the version and commit the
//!   binary's `-V` shows, whether that commit is `main` and
//!   `main@origin`, its state, and a suffixed version. A binary whose
//!   `-V` carries no commit is reported as unknown. It refuses
//!   nothing: which builds
//!   may be installed is the release process's call, a cycle's Land
//!   here, and a project releasing from a branch or a tag makes it
//!   differently.
//! - It refuses only when the copy itself would be wrong, every reason
//!   listed: no binary where the config says after the build, a binary
//!   whose `-V` will not run, or a missing install directory.
//! - The copy is a temporary file beside the destination renamed into
//!   place, so the binary installed is the one tested, a running copy
//!   of the old one is undisturbed, and a failed copy leaves the old
//!   one.
//! - `[install] release` and `dev`, optional command lists in
//!   `[build]`'s shape, replace the copy when present: the build, the
//!   report, and the refusals are the same, and the list runs instead
//!   of the copy. Its placeholders are the keys the command reads,
//!   resolved for the run: `{build.release-bin}` and
//!   `{install.release-dir}`, or `{build.dev-bin}` and
//!   `{install.dev-dir}`, `--dir` applied, so the list names every
//!   path it writes. With a list, the file name, `-dev` included, is
//!   the list's to write.
//! - `--dry-run` builds and reports, and copies nothing.
//! - `--dir <DIR>` copies into `DIR` instead of the configured
//!   directory, for one run, so a test of install leaves the PATH
//!   alone. A relative `DIR` is taken against the current directory,
//!   as any path argument is, and the workspace needs no directory key
//!   for it.
//! - A workspace with no directory key for the build has nothing to
//!   install, and the command says so before building anything.

use std::path::{Path, PathBuf};

use clap::Args;
use log::{debug, info};

use crate::build_cmd::{BuildParams, build_params, dev_bin, release_bin};
use crate::context::Context;
use crate::options_flags::dry_run::DryRunFlag;
use crate::subcommand::SubcommandRunner;

/// The trunk the report compares the binary's commit with.
const TRUNK: &str = "main";

/// Copy the release build, or with `--dev` the dev build, into the
/// install directory.
#[derive(Args, Debug)]
pub struct InstallArgs {
    /// Install the dev build as `<name>-dev`, by `[build] dev` and
    /// `[install] dev-dir`, instead of the release
    #[arg(short = 'd', long)]
    pub dev: bool,

    #[command(flatten)]
    pub dry_run: DryRunFlag,

    /// Workspace to install from [default: the workspace containing
    /// the current directory]
    #[arg(short = 'R', long, value_name = "DIR")]
    pub repo: Option<PathBuf>,

    /// Copy into DIR instead of `[install] release-dir`, or `dev-dir`
    /// with `--dev`, for this run
    #[arg(long, value_name = "DIR")]
    pub dir: Option<PathBuf>,
}

/// Retired: `install-dev`, now `install --dev`, refused naming it.
/// Its flags are kept so an old invocation parses and is told the fix.
#[derive(Args, Debug)]
pub struct InstallDevArgs {
    #[command(flatten)]
    pub dry_run: DryRunFlag,

    /// Workspace to install from [default: the workspace containing
    /// the current directory]
    #[arg(short = 'R', long, value_name = "DIR")]
    pub repo: Option<PathBuf>,

    /// Copy into DIR instead of `[install] dev-dir`, for this run
    #[arg(long, value_name = "DIR")]
    pub dir: Option<PathBuf>,
}

/// What the binary's `-V` says: its version and, from the build
/// metadata after `+`, its commit and the state after it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reported {
    /// The version before any `+`.
    pub version: String,
    /// The commit prefix after `+`, when the build reports one.
    pub commit: Option<String>,
    /// The state after the commit, `dirty` or `unknown`, when not clean.
    pub state: Option<String>,
}

/// Everything the report and the refusals judge, gathered before
/// either is made.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Facts {
    /// The local trunk's commit, `None` when there is no such bookmark.
    pub trunk: Option<String>,
    /// The remote trunk's commit, `None` when it is not known.
    pub trunk_origin: Option<String>,
    /// The manifest's version.
    pub version: String,
    /// True when the binary is there.
    pub bin_exists: bool,
    /// What the binary's `-V` said, `None` when it could not be run or
    /// read.
    pub reported: Option<Reported>,
    /// True when the destination directory exists.
    pub dest_dir_exists: bool,
}

/// Per-invocation install inputs: the build to run first, where its
/// binary is and where it goes, and whether to copy.
#[derive(Debug)]
pub struct InstallParams {
    /// `install` or `install --dev`, prefixing the run's messages.
    pub label: &'static str,
    /// `build.release-bin` or `build.dev-bin`, the key naming the
    /// binary, for a refusal to point at.
    pub bin_key: &'static str,
    /// The work repo root.
    pub root: PathBuf,
    /// The build, `vc-x1 build`'s, with `--dev` or not, run before
    /// anything else.
    pub build: BuildParams,
    /// The binary, `[build] release-bin` or `[build] dev-bin`.
    pub bin: PathBuf,
    /// The destination, `--dir` or `[install] release-dir` or
    /// `dev-dir` joined with the binary's name, `suffix` appended.
    pub dest: PathBuf,
    /// `[install] dev-suffix` for the dev build, `-dev` when absent,
    /// and empty for the release.
    pub suffix: String,
    /// `[install] release` or `dev`, run in place of the copy when
    /// present.
    pub list: Option<Vec<String>>,
    /// `install.release` or `install.dev`, naming the list in its
    /// messages.
    pub list_key: &'static str,
    /// The keys whose resolved values the list's placeholders name,
    /// the binary's, the directory's, and for the dev build the
    /// suffix's.
    pub names: &'static [&'static str],
    /// Build and report, and copy nothing.
    pub dry_run: bool,
}

impl TryFrom<&InstallArgs> for InstallParams {
    type Error = String;

    /// The release, or the dev build with `--dev`: see
    /// [`install_params`].
    fn try_from(a: &InstallArgs) -> Result<Self, String> {
        install_params(a.dev, a.repo.as_deref(), a.dir.as_deref(), a.dry_run.value)
    }
}

impl TryFrom<&InstallDevArgs> for InstallParams {
    type Error = String;

    /// Refused: `install-dev` is `install --dev`.
    fn try_from(_: &InstallDevArgs) -> Result<Self, String> {
        Err(crate::build_cmd::retired_dev("install"))
    }
}

/// Resolve the workspace, the install directory, `dir` before
/// `[install] release-dir` or `dev-dir`, the build, the dev build and
/// its suffix when `dev`, and the optional install list. A missing
/// config key, and a dev copy that would replace the release, are
/// errors here, before the build runs, and every fact about the binary
/// is gathered after it.
pub fn install_params(
    dev: bool,
    repo: Option<&Path>,
    dir: Option<&Path>,
    dry_run: bool,
) -> Result<InstallParams, String> {
    let (label, dir_key, list_key) = if dev {
        ("install --dev", "install.dev-dir", "install.dev")
    } else {
        ("install", "install.release-dir", "install.release")
    };
    let (bin_key, names): (&str, &'static [&'static str]) = if dev {
        (
            "build.dev-bin",
            &["build.dev-bin", "install.dev-dir", "install.dev-suffix"],
        )
    } else {
        (
            "build.release-bin",
            &["build.release-bin", "install.release-dir"],
        )
    };
    let root = match repo {
        Some(p) => crate::common::find_workspace_root_from(p)
            .ok_or_else(|| format!("{label}: '{}' is not in a vc-x1 workspace", p.display()))?,
        None => crate::common::find_workspace_root()
            .ok_or_else(|| format!("{label}: not in a vc-x1 workspace (no config found)"))?,
    };
    let dest_dir = dest_dir(&root, dir, dir_key).map_err(|e| format!("{label}: {e}"))?;
    let build = build_params(dev, Some(&root))?;
    let bin = if dev {
        dev_bin(&root)?
    } else {
        release_bin(&root)?
    };
    let suffix = if dev {
        dev_suffix(&root).map_err(|e| format!("{label}: {e}"))?
    } else {
        String::new()
    };
    let dest = dest_dir.join(dest_name(&bin, &suffix).map_err(|e| format!("{label}: {e}"))?);
    let list = crate::command_list::load_optional(&root, list_key, label)?;
    match &list {
        Some(list) => crate::command_list::check_placeholders(list, names, list_key, label)?,
        None if dev => guard_release(&root, &dest).map_err(|e| format!("{label}: {e}"))?,
        None => {}
    }
    Ok(InstallParams {
        label,
        bin_key,
        root,
        build,
        bin,
        dest,
        suffix,
        list,
        list_key,
        names,
        dry_run,
    })
}

/// The name `bin` takes in the install directory: its own, with
/// `suffix` appended, empty for the release.
fn dest_name(bin: &Path, suffix: &str) -> Result<String, String> {
    let name = bin
        .file_name()
        .ok_or_else(|| format!("'{}' names no file", bin.display()))?
        .to_string_lossy();
    Ok(format!("{name}{suffix}"))
}

/// `[install] dev-suffix` at `root`, the schema's default, `-dev`,
/// when absent. A suffix holding a path separator is an error, since
/// it would move the copy out of the install directory.
fn dev_suffix(root: &Path) -> Result<String, String> {
    let cfg = crate::config_md::load(root)
        .map_err(|e| e.to_string())?
        .ok_or_else(|| format!("no config in '{}'", root.display()))?;
    let suffix = match crate::toml_simple::toml_get(&cfg.map, "install.dev-suffix") {
        Some(s) => s.clone(),
        None => crate::config_schema::INSTALL_DEV_SUFFIX_DEFAULT.to_string(),
    };
    if suffix.contains(std::path::is_separator) {
        return Err(format!(
            "{}: `install.dev-suffix` is '{suffix}', which holds a path separator",
            cfg.path.display()
        ));
    }
    Ok(suffix)
}

/// Refuse a dev copy to `dest` that is the release's own destination,
/// `[install] release-dir` joined with the release's file name, since
/// it would replace the release. A workspace with no release install
/// has none to replace.
fn guard_release(root: &Path, dest: &Path) -> Result<(), String> {
    let (Ok(dir), Ok(bin)) = (install_dir(root, "install.release-dir"), release_bin(root)) else {
        return Ok(());
    };
    let release = dir.join(dest_name(&bin, "")?);
    if !same_place(dest, &release) {
        return Ok(());
    }
    Err(format!(
        "the dev build's destination '{}' is the release's, so the copy would replace it: give \
         `install.dev-suffix` a value, or put `install.dev-dir` or --dir elsewhere",
        dest.display()
    ))
}

/// True when `a` and `b` name the same file: the same file name in the
/// same directory, each directory compared canonical when it exists.
fn same_place(a: &Path, b: &Path) -> bool {
    // OK: a directory that does not exist is compared as written
    let dir = |p: &Path| {
        p.parent()
            .map(|d| std::fs::canonicalize(d).unwrap_or_else(|_| d.to_path_buf()))
    };
    a.file_name() == b.file_name() && dir(a) == dir(b)
}

/// Gather the facts about the binary at `bin`, after the build, and
/// about the trunk of the work repo at `root`.
pub fn gather(root: &Path, bin: &Path, dest: &Path) -> Result<Facts, String> {
    Ok(Facts {
        trunk: crate::jj::cid_of(root, TRUNK).ok(),
        trunk_origin: crate::jj::cid_of(root, &format!("{TRUNK}@origin")).ok(),
        version: manifest_version(root)?,
        bin_exists: bin.is_file(),
        reported: run_version(bin).as_deref().and_then(parse_reported),
        dest_dir_exists: dest.parent().is_some_and(Path::is_dir),
    })
}

/// The directory the copy goes to: `dir`, the `--dir` value, against
/// the current directory when relative, when given, else the
/// directory `key` names at `root`. Absolute either way, since an
/// install list runs from `root` and takes it as a placeholder.
fn dest_dir(root: &Path, dir: Option<&Path>, key: &str) -> Result<PathBuf, String> {
    match dir {
        Some(d) if d.is_absolute() => Ok(d.to_path_buf()),
        Some(d) => std::env::current_dir()
            .map(|cwd| cwd.join(d))
            .map_err(|e| format!("--dir '{}': no current directory: {e}", d.display())),
        None => install_dir(root, key),
    }
}

/// The directory `key`, `install.release-dir` or `install.dev-dir`,
/// names at `root`: `~` and `~/...` against the home directory, any
/// other relative value against the config file's directory, an
/// absolute one as is. Its absence is the workspace having nothing of
/// that build to install.
pub fn install_dir(root: &Path, key: &str) -> Result<PathBuf, String> {
    let cfg = crate::config_md::load(root)
        .map_err(|e| e.to_string())?
        .ok_or_else(|| format!("no config in '{}'", root.display()))?;
    let value = crate::toml_simple::toml_get(&cfg.map, key).ok_or_else(|| {
        format!(
            "{}: no `{key}`, so this workspace has nothing to install. Name the \
             directory the build is copied into, such as `~/.cargo/bin` (see `vc-x1 \
             config -s work`), or pass --dir",
            cfg.path.display()
        )
    })?;
    // OK: a loaded config's path is a file, so it has a parent
    let cfg_dir = cfg.path.parent().unwrap_or(root);
    expand_dir(
        cfg_dir,
        key,
        value,
        crate::jj::session::home_dir().as_deref(),
    )
}

/// Expand the directory `key`'s `value`: `~` against `home`, else
/// against `cfg_dir` when relative.
fn expand_dir(
    cfg_dir: &Path,
    key: &str,
    value: &str,
    home: Option<&Path>,
) -> Result<PathBuf, String> {
    let rest = if value == "~" {
        Some("")
    } else {
        value.strip_prefix("~/")
    };
    match rest {
        Some(rest) => home
            .map(|h| h.join(rest))
            .ok_or_else(|| format!("`{key}` is '{value}' and HOME is not set")),
        None => Ok(crate::common::resolve_repo_path(cfg_dir, value)),
    }
}

/// The manifest's version, `[package] version` in the `Cargo.toml` at
/// `root`.
pub fn manifest_version(root: &Path) -> Result<String, String> {
    let path = root.join("Cargo.toml");
    let map = crate::toml_simple::toml_load(&path)
        .map_err(|e| format!("cannot read '{}': {e}", path.display()))?;
    crate::toml_simple::toml_get(&map, "package.version")
        .cloned()
        .ok_or_else(|| format!("'{}' has no `[package] version`", path.display()))
}

/// Run `bin -V` and return what it prints, `None` when it cannot be
/// run or fails.
pub(crate) fn run_version(bin: &Path) -> Option<String> {
    // Register entry 7 (clippy.toml): install runs the binary it is
    // about to copy, `-V` alone, to report it.
    #[allow(clippy::disallowed_methods)]
    let out = std::process::Command::new(bin).arg("-V").output().ok()?;
    if !out.status.success() {
        return None;
    }
    String::from_utf8(out.stdout).ok()
}

/// Parse `-V`'s output: the first line `<name> <version>[+<commit>[.<state>]] ...`
/// whose second word starts with a digit, so a line printed before the
/// version is passed over. `None` when no line has a version, which
/// install refuses as unreadable.
pub fn parse_reported(output: &str) -> Option<Reported> {
    let word = output.lines().find_map(|line| {
        line.split_whitespace()
            .nth(1)
            .filter(|w| w.starts_with(|c: char| c.is_ascii_digit()))
    })?;
    let (version, meta) = match word.split_once('+') {
        Some((v, m)) => (v, Some(m)),
        None => (word, None),
    };
    let (commit, state) = match meta {
        None => (None, None),
        Some(m) => match m.split_once('.') {
            Some((c, s)) => (Some(c.to_string()), Some(s.to_string())),
            None => (Some(m.to_string()), None),
        },
    };
    Some(Reported {
        version: version.to_string(),
        commit,
        state,
    })
}

/// True when the commit prefix `c` names the commit id `id`.
fn names(c: &str, id: Option<&String>) -> bool {
    id.is_some_and(|id| id.starts_with(c))
}

/// The report: what is being copied, one fact per line, for the user
/// to judge. Nothing in it refuses.
pub fn report(f: &Facts) -> Vec<String> {
    let mut out = Vec::new();
    let Some(r) = &f.reported else {
        return out;
    };
    let mut version = format!("version {}", r.version);
    if r.version.contains('-') {
        version.push_str(", a suffixed (pre-release) version");
    }
    if r.version != f.version {
        version.push_str(&format!(", the manifest's is {}", f.version));
    }
    out.push(version);
    match &r.commit {
        None => {
            out.push("commit unknown: the binary reports none".to_string());
            out.push("state unknown".to_string());
        }
        Some(c) => {
            let on_trunk = names(c, f.trunk.as_ref());
            let on_origin = names(c, f.trunk_origin.as_ref());
            let where_ = match (on_trunk, on_origin) {
                (true, true) => format!("`{TRUNK}` and `{TRUNK}@origin`"),
                (true, false) => format!("`{TRUNK}`, not yet `{TRUNK}@origin`"),
                (false, true) => format!("`{TRUNK}@origin`, not the local `{TRUNK}`"),
                (false, false) => format!("not `{TRUNK}`"),
            };
            out.push(format!("commit {c}, {where_}"));
            // A commit with no state after it is a clean build.
            let state = match &r.state {
                Some(s) => s.as_str(),
                None => "clean",
            };
            out.push(format!("state {state}"));
        }
    }
    out
}

/// Every reason the copy itself would be wrong, empty when it may go,
/// `bin_key` the key naming `bin`.
pub fn refusals(f: &Facts, bin: &Path, dest: &Path, bin_key: &str) -> Vec<String> {
    let mut out = Vec::new();
    if !f.bin_exists {
        out.push(format!(
            "no binary at '{}' after the build: check `{bin_key}`",
            bin.display()
        ));
    } else if f.reported.is_none() {
        out.push(format!("'{}' -V could not be run or read", bin.display()));
    }
    if !f.dest_dir_exists {
        // OK: dest is a directory joined with a file name, so it has a parent
        let dir = dest.parent().unwrap_or(dest);
        out.push(format!(
            "the install directory '{}' does not exist",
            dir.display()
        ));
    }
    out
}

/// Copy `bin` to `dest` as a temporary file beside it renamed into
/// place, so `dest` is never half written and a running copy of the
/// old binary is undisturbed. The temporary file is removed on failure.
pub fn deploy(bin: &Path, dest: &Path) -> Result<(), String> {
    // OK: dest is a directory joined with a file name, so both exist
    let dir = dest.parent().unwrap_or(Path::new("."));
    // OK: dest is joined with the binary's file name, so it has one
    let name = dest
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default();
    let tmp = dir.join(format!(".{name}.vc-x1-install"));
    let result = std::fs::copy(bin, &tmp)
        .map_err(|e| format!("cannot copy to '{}': {e}", tmp.display()))
        .and_then(|_| {
            std::fs::rename(&tmp, dest).map_err(|e| {
                format!(
                    "cannot move '{}' into '{}': {e}",
                    tmp.display(),
                    dest.display()
                )
            })
        });
    if result.is_err() {
        std::fs::remove_file(&tmp).ok();
    }
    result
}

impl SubcommandRunner for InstallArgs {
    type Params = InstallParams;

    /// Delegate to the `TryFrom<&InstallArgs>` impl above.
    fn to_params(&self) -> Result<Self::Params, String> {
        InstallParams::try_from(self)
    }

    /// Run the `install` op (`ctx` unused: the op is fully
    /// parameterized by `Params`).
    fn run(_ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        install(params)
    }
}

impl SubcommandRunner for InstallDevArgs {
    type Params = InstallParams;

    /// Delegate to the `TryFrom<&InstallDevArgs>` impl above.
    fn to_params(&self) -> Result<Self::Params, String> {
        InstallParams::try_from(self)
    }

    /// Run the same op as `install`, its params naming the dev build.
    fn run(_ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        install(params)
    }
}

/// Run the build, as `vc-x1 build`, with `--dev` or not, does, then
/// report the binary and copy it unless refused or a dry run. Cargo
/// rebuilds only what changed, so with nothing changed the binary
/// already tested is the one copied.
pub fn install(params: &InstallParams) -> Result<(), Box<dyn std::error::Error>> {
    debug!("{}: entry params={params:?}", params.label);
    crate::build_cmd::build(&params.build)?;
    let facts = gather(&params.root, &params.bin, &params.dest)
        .map_err(|e| format!("{}: {e}", params.label))?;
    copy_reported(params, &facts)
}

/// Print the report, refuse with every reason at once when the copy
/// would be wrong, then, unless it is a dry run, run the install list
/// when there is one, else copy the binary to its destination.
pub fn copy_reported(
    params: &InstallParams,
    facts: &Facts,
) -> Result<(), Box<dyn std::error::Error>> {
    let (label, bin, dest) = (params.label, &params.bin, &params.dest);
    match &params.list {
        Some(_) => info!("{label}: '{}' -> list `{}`", bin.display(), params.list_key),
        None => info!("{label}: '{}' -> '{}'", bin.display(), dest.display()),
    }
    for line in report(facts) {
        info!("{label}:   {line}");
    }
    let reasons = refusals(facts, bin, dest, params.bin_key);
    if !reasons.is_empty() {
        let list: String = reasons.iter().map(|r| format!("\n  - {r}")).collect();
        return Err(format!(
            "{label}: refused, nothing copied to '{}':{list}",
            dest.display()
        )
        .into());
    }
    if params.dry_run {
        match &params.list {
            Some(_) => info!("{label}: [dry-run] ran nothing of `{}`", params.list_key),
            None => info!("{label}: [dry-run] copied nothing"),
        }
        return Ok(());
    }
    if let Some(list) = &params.list {
        return run_list(params, list);
    }
    deploy(bin, dest).map_err(|e| format!("{label}: {e}"))?;
    info!("{label}: copied");
    Ok(())
}

/// Run the install list from the root, in place of the copy, its
/// placeholders the binary and the directory, resolved for the run.
fn run_list(params: &InstallParams, list: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let bin = params.bin.to_string_lossy();
    // OK: dest is a directory joined with a file name, so it has a parent
    let dir = params
        .dest
        .parent()
        .unwrap_or(&params.dest)
        .to_string_lossy();
    let mut vars = vec![
        (params.names[0], bin.as_ref()),
        (params.names[1], dir.as_ref()),
    ];
    if let Some(name) = params.names.get(2) {
        vars.push((name, params.suffix.as_str()));
    }
    crate::command_list::run(
        &params.root,
        params.list_key,
        list,
        &[],
        &vars,
        params.label,
    )
}

