89	/// Per-invocation run inputs: the build to run first, its binary, the
90	/// manifest's version to check it against, and the arguments.
91	#[derive(Debug)]
92	pub struct RunParams {
93	    /// `run` or `run --dev`, prefixing the run's messages.
94	    pub label: &'static str,
95	    /// `build.release-bin` or `build.dev-bin`, for a message to point
96	    /// at.
97	    pub bin_key: &'static str,
98	    /// The build, `vc-x1 build`'s or `vc-x1 build-dev`'s, a dry run
99	    /// when this one is.
100	    pub build: BuildParams,
101	    /// The binary to run.
102	    pub bin: PathBuf,
103	    /// The manifest's version, `None` when the root has no
104	    /// `Cargo.toml` to read it from.
105	    pub version: Option<String>,
106	    /// The arguments, passed untouched.
107	    pub args: Vec<OsString>,
108	    /// Print the build's list and the command, and run nothing.
109	    pub dry_run: bool,
110	}
111	
112	impl TryFrom<&RunArgs> for RunParams {
113	    type Error = String;
114	
115	    /// The release, or the dev build with `--dev`: see
116	    /// [`run_params`].
117	    fn try_from(a: &RunArgs) -> Result<Self, String> {
118	        run_params(a.dev, a.repo.as_deref(), &a.args, a.dry_run.value)
119	    }
120	}
121	
122	impl TryFrom<&RunDevArgs> for RunParams {
123	    type Error = String;
124	
125	    /// Refused: `run-dev` is `run --dev`.
126	    fn try_from(_: &RunDevArgs) -> Result<Self, String> {
127	        Err(crate::build_cmd::retired_dev("run"))
128	    }
129	}
