131	/// Resolve the build, the dev build when `dev`, and its binary. A
132	/// missing config key is an error here, before anything runs.
133	pub fn run_params(
134	    dev: bool,
135	    repo: Option<&Path>,
136	    args: &[OsString],
137	    dry_run: bool,
138	) -> Result<RunParams, String> {
139	    let (label, bin_key) = if dev {
140	        ("run --dev", "build.dev-bin")
141	    } else {
142	        ("run", "build.release-bin")
143	    };
144	    let mut build = build_params(dev, repo)?;
145	    build.dry_run = dry_run;
146	    let bin = if dev {
147	        dev_bin(&build.root)?
148	    } else {
149	        release_bin(&build.root)?
150	    };
151	    let version = crate::install_cmd::manifest_version(&build.root).ok();
152	    Ok(RunParams {
153	        label,
154	        bin_key,
155	        build,
156	        bin,
157	        version,
158	        args: args.to_vec(),
159	        dry_run,
160	    })
161	}
162	
163	/// Run `run`, with `--dev` or not, for `main`: the binary's exit code is
164	/// vc-x1's, so a failing run fails the same way, and any error
165	/// before it runs is logged and fails.
166	pub fn dispatch(params: Result<RunParams, String>) -> ExitCode {
167	    let params = match params {
168	        Ok(p) => p,
169	        Err(e) => {
170	            error!("{e}");
171	            return ExitCode::FAILURE;
172	        }
173	    };
174	    crate::bm_track("enter", params.label);
175	    let code = match run(&params) {
176	        Ok(code) => exit_code(code),
177	        Err(e) => {
178	            error!("{e}");
179	            ExitCode::FAILURE
180	        }
181	    };
182	    crate::bm_track("exit ", params.label);
183	    code
184	}
185	
186	/// The process exit code for a binary's `code`.
187	fn exit_code(code: i32) -> ExitCode {
188	    // OK: a code outside 0..=255, which no Unix exit status is, is a failure
189	    ExitCode::from(u8::try_from(code).unwrap_or(1))
190	}
191	
192	/// Build, check the binary, and run it with the arguments, returning
193	/// its exit code. A dry run prints the build's list and the command,
194	/// and returns 0.
195	pub fn run(params: &RunParams) -> Result<i32, Box<dyn std::error::Error>> {
196	    debug!("{}: entry params={params:?}", params.label);
197	    crate::build_cmd::build(&params.build)?;
198	    let shown = shown_command(&params.bin, &params.args);
199	    if params.dry_run {
200	        info!("{}: [dry-run] would run {shown}", params.label);
201	        return Ok(0);
202	    }
203	    if !params.bin.is_file() {
204	        return Err(format!(
205	            "{}: no binary at '{}' after the build: check `{}`",
206	            params.label,
207	            params.bin.display(),
208	            params.bin_key
209	        )
210	        .into());
211	    }
212	    let reported = crate::install_cmd::run_version(&params.bin)
213	        .as_deref()
214	        .and_then(crate::install_cmd::parse_reported);
215	    if let Some(note) = version_note(
216	        reported.as_ref().map(|r| r.version.as_str()),
217	        params.version.as_deref(),
218	    ) {
219	        warn!(
220	            "{}: '{}' {note}: check `{}`",
221	            params.label,
222	            params.bin.display(),
223	            params.bin_key
224	        );
225	    }
226	    info!("{}: {shown}", params.label);
227	    // Register entry 7 (clippy.toml): run and run-dev run the
228	    // workspace's build, which is the whole job of the command.
229	    #[allow(clippy::disallowed_methods)]
230	    let status = std::process::Command::new(&params.bin)
231	        .args(&params.args)
232	        .status()
233	        .map_err(|e| {
234	            format!(
235	                "{}: cannot run '{}': {e}",
236	                params.label,
237	                params.bin.display()
238	            )
239	        })?;
240	    match status.code() {
241	        Some(code) => Ok(code),
242	        None => Err(format!("{}: '{}' {status}", params.label, params.bin.display()).into()),
243	    }
244	}
245	
246	/// The command as the log shows it: the binary and its arguments.
247	fn shown_command(bin: &Path, args: &[OsString]) -> String {
248	    let mut out = format!("'{}'", bin.display());
249	    for a in args {
250	        out.push(' ');
251	        out.push_str(&a.to_string_lossy());
252	    }
253	    out
254	}
255	
256	/// The warning for a binary reporting `reported` when the manifest
257	/// says `manifest`, `None` when they agree or either is unknown.
258	fn version_note(reported: Option<&str>, manifest: Option<&str>) -> Option<String> {
259	    let (reported, manifest) = (reported?, manifest?);
260	    (reported != manifest).then(|| format!("reports {reported}, the manifest's is {manifest}"))
261	}
262	
263	/// What a completion forward asks: the build whose binary answers,
264	/// the workspace `-R` named, the words it is given, its own name
265	/// first, and the cursor's index among them when the shell gave one.
266	#[derive(Debug, PartialEq, Eq)]
267	pub struct Forward {
268	    /// `run --dev`'s dev build rather than `run`'s release.
269	    pub dev: bool,
270	    /// The workspace `-R` named, else the current directory's.
271	    pub repo: Option<PathBuf>,
272	    /// The words for the binary, the first standing for its name.
273	    pub words: Vec<String>,
274	    /// The cursor's index in `words`, when the shell passed one.
275	    pub index: Option<usize>,
276	}
277	
278	/// Plan a completion forward from the words a shell passes, the
279	/// program's name first, and the cursor's index among them, or
280	/// `None` when the words are not `run`'s arguments and clap completes
281	/// them itself.
282	///
283	/// - The subcommand is the first word after vc-x1's own flags, and
284	///   only `run` is forwarded. Any other subcommand is clap's.
285	/// - The subcommand's own options, `--dev`, `-d`, `--dry-run`, `-R
286	///   DIR`, `--repo DIR`, and `--repo=DIR`, are skipped, `--dev`
287	///   choosing the dev build, and `--` ends them. A word
288	///   at the cursor that starts with `-` before any argument is
289	///   clap's, so `run --d<TAB>` offers `--dry-run`.
290	/// - The cursor on the subcommand or its options is clap's too, so
291	///   only the arguments are forwarded, with the index shifted to
292	///   match.
293	pub fn plan_forward(words: &[String], index: Option<usize>) -> Option<Forward> {
294	    // OK: with no index the shell completes the last word
295	    let cursor = index.unwrap_or(words.len().saturating_sub(1));
296	    let sub = words
297	        .iter()
298	        .enumerate()
299	        .skip(1)
300	        .find(|(_, w)| !w.starts_with('-'))
301	        .map(|(i, _)| i)?;
302	    if words[sub] != "run" {
303	        return None;
304	    }
305	    let mut dev = false;
306	    let mut repo = None;
307	    let mut i = sub + 1;
308	    while i < words.len() && i < cursor {
309	        let w = words[i].as_str();
310	        if w == "--" {
311	            i += 1;
312	            break;
313	        }
314	        if w == "--dry-run" {
315	            i += 1;
316	        } else if w == "--dev" || w == "-d" {
317	            dev = true;
318	            i += 1;
319	        } else if w == "-R" || w == "--repo" {
320	            repo = words.get(i + 1).map(PathBuf::from);
321	            i += 2;
322	        } else if let Some(dir) = w.strip_prefix("--repo=") {
323	            repo = Some(PathBuf::from(dir));
324	            i += 1;
325	        } else {
326	            break;
327	        }
328	    }
329	    if cursor < i || (cursor == i && words[i].starts_with('-') && words[i - 1] != "--") {
330	        return None;
331	    }
332	    let mut forwarded = vec![words[0].clone()];
333	    forwarded.extend(words[i..].iter().cloned());
334	    Some(Forward {
335	        dev,
336	        repo,
337	        words: forwarded,
338	        index: index.map(|n| n - (i - 1)),
339	    })
340	}
341	
342	/// Forward a completion request for `run`'s arguments
343	/// to the binary it would run, and exit with its answer. Called by
344	/// `main` before clap's completion, which it leaves alone for every
345	/// other request.
346	///
347	/// A shell asks by running `COMPLETE=<shell> vc-x1 -- <words>` with
348	/// the cursor in `_CLAP_COMPLETE_INDEX` for most shells. The binary
349	/// is asked the same way, `COMPLETE` and the shell's other variables
350	/// inherited and the index shifted, so it answers in the protocol
351	/// the shell reads. Its config is the workspace's the shell is in, or
352	/// `-R`'s, and it is never built: no binary, or none that answers,
353	/// prints nothing.
354	pub fn forward_completion() {
355	    if std::env::var_os("COMPLETE").is_none_or(|v| v.is_empty() || v == "0") {
356	        return;
357	    }
358	    let args: Vec<String> = std::env::args().collect();
359	    if args.get(1).map(String::as_str) != Some("--") {
360	        return;
361	    }
362	    let index = std::env::var("_CLAP_COMPLETE_INDEX")
363	        .ok()
364	        .and_then(|i| i.parse().ok());
365	    let Some(plan) = plan_forward(&args[2..], index) else {
366	        return;
367	    };
368	    let code = forward(&plan);
369	    std::process::exit(code);
370	}
371	
372	/// Ask the binary `plan` names, returning its exit code, 0 when there
373	/// is none to ask.
374	fn forward(plan: &Forward) -> i32 {
375	    let root = match &plan.repo {
376	        Some(p) => crate::common::find_workspace_root_from(p),
377	        None => crate::common::find_workspace_root(),
378	    };
379	    let Some(root) = root else {
380	        return 0;
381	    };
382	    let bin = if plan.dev {
383	        dev_bin(&root)
384	    } else {
385	        release_bin(&root)
386	    };
387	    let Ok(bin) = bin else {
388	        return 0;
389	    };
390	    if !bin.is_file() {
391	        return 0;
392	    }
393	    // Register entry 7 (clippy.toml): the completion forward asks the
394	    // workspace's build, in clap's completion mode, for its own words.
395	    #[allow(clippy::disallowed_methods)]
396	    let mut cmd = std::process::Command::new(&bin);
397	    cmd.arg("--").args(&plan.words);
398	    if let Some(index) = plan.index {
399	        cmd.env("_CLAP_COMPLETE_INDEX", index.to_string());
400	    }
401	    match cmd.status() {
402	        // OK: a binary killed by a signal answered nothing
403	        Ok(status) => status.code().unwrap_or(0),
404	        Err(_) => 0,
405	    }
406	}
